import React, { useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ConnLogo, Ico } from './Ico';
import { useSnack } from './Snack';
import {
  useW06Company,
  useW06Score,
  useW06Scopes,
  useW06Categories,
  useW06Assessments,
  useW06Recs,
  useW06Setup,
  useW06Readiness,
  useW06Docs,
} from './adapters';
import { publicAssetUrl } from '../constants/brand';
import { useExpertModeContext } from '../context/ExpertModeContext';
import documentService from '../services/documentService';
import {
  PAGE_HREF,
  uploadHref,
  type DataTab,
  type PageKey,
} from './paths';
import {
  ActionRow,
  BarChart,
  Card,
  CheckRow,
  Chip,
  Dl,
  Figure,
  MeterRow,
  Modal,
  Note,
  PageHead,
  RecRow,
  ScopeCard,
  inr,
} from './primitives';
import {
  CONNECTORS,
  PLANT,
} from './seed';

function goKey(navigate: ReturnType<typeof useNavigate>, key: PageKey) {
  navigate(PAGE_HREF[key]);
}

export const HomePage: React.FC = () => {
  const navigate = useNavigate();
  const { expertMode } = useExpertModeContext();
  const x = expertMode;
  const company = useW06Company();
  const { data: score } = useW06Score();
  const { data: scopes } = useW06Scopes();
  const { data: catBundle } = useW06Categories();
  const { data: assessBundle } = useW06Assessments();
  const { data: recBundle } = useW06Recs();
  const { data: setup } = useW06Setup();
  const { data: readiness } = useW06Readiness();
  const done = setup.filter((s) => s.done).length;
  return (
    <>
      <PageHead page="dashboard" />
      <div className="stack">
        <div className="grid g-hero">
          <Card title="Your carbon score" icon="score">
            <div className="score-line">
              <span className="score">{score.score}</span>
              <span className="score-of">/ 100</span>
            </div>
            <div className="score-chips">
              <Chip>{score.label}</Chip>
              <Chip>{score.track}</Chip>
            </div>
            <div className="month">
              <b>{score.monthTotal}</b>
              <span>kg CO₂ this month{x ? ` · ${score.tco2e} tCO₂e` : ''}</span>
            </div>
            {x ? (
              <p className="meta-line">{score.delta} · trend {score.trend.join(' → ')} · GST {company.gst}</p>
            ) : null}
          </Card>
          <section className="card nba">
            <h2><Ico name="next" />What to do next</h2>
            <p>Upload your latest electricity bill to refresh this month's reading.</p>
            <div className="btn-row">
              <button type="button" className="btn" onClick={() => goKey(navigate, 'upload')}>
                <Ico name="ctaUpload" wrap={false} />Upload a bill
              </button>
              {x ? (
                <button type="button" className="btn ghost" onClick={() => goKey(navigate, 'footprint')}>
                  <Ico name="view" wrap={false} />View footprint
                </button>
              ) : null}
            </div>
          </section>
        </div>
        <Card title="Finish setup" icon="gapTick" tail={`${done} of ${setup.length} done`}>
          {setup.map((s) => (
            <CheckRow
              key={s.id}
              done={s.done}
              k={s.k}
              sub={s.sub}
              action={
                s.done ? undefined : (
                  <span className="go">
                    <button type="button" className="btn sm ghost" onClick={() => goKey(navigate, s.go as PageKey)}>
                      Do this
                    </button>
                  </span>
                )
              }
            />
          ))}
        </Card>
        <div>
          <div className="block-head">
            <Ico name="scopeCard" />
            <h2>This month by scope</h2>
            <span className="tail">{score.monthTotal} kg total</span>
          </div>
          <div className="grid g-3">
            {scopes.map((s) => (
              <ScopeCard key={s.tag} scope={s} />
            ))}
          </div>
          {x ? <Note>Spend-based calculation · ISO 14064 aligned</Note> : null}
        </div>
        {x ? (
          <>
            <Card title="This month by category" icon="catCard">
              {catBundle.cats.map((c) => (
                <MeterRow
                  key={c.k}
                  label={c.k}
                  value={`${c.v.toFixed(2)} kg`}
                  pct={Math.round((c.v / catBundle.max) * 100)}
                  color={c.color}
                  icon={c.ico}
                  pctText=""
                />
              ))}
              <Note>Biggest source: {catBundle.hotspot.k}, {catBundle.hotspot.v} kg from {catBundle.hotspot.vendor}</Note>
            </Card>
            <div className="grid g-2">
              <Card title="Last 3 months" icon="trend">
                <BarChart
                  bars={assessBundle.rows.map((a) => ({ label: a.label, kg: a.kg }))}
                  max={assessBundle.chartMax}
                  axis={`kg CO₂ per month · ${score.deltaKg} kg lower than previous (−${score.deltaPct}%)`}
                />
              </Card>
              <Card title="Compliance readiness" icon="readiness">
                {readiness.map((r) => (
                  <MeterRow key={r.name} label={r.name} value={`${r.pct}%`} pct={r.pct} color="var(--brand-solid)" icon="fwMark" pctText="" />
                ))}
                <Note>Open Compliance to see what is missing.</Note>
              </Card>
            </div>
          </>
        ) : null}
        <Card title="Ways to reduce" icon="recsCard" tail={x ? `${recBundle.recs.length} ideas · ranked by impact` : `${recBundle.recs.length} ideas`}>
          {recBundle.recs.map((r) => (
            <RecRow key={r.id} title={r.title} cost={r.cost} payback={r.payback} reduction={r.reduction} ico={r.ico} />
          ))}
          <Note>{recBundle.reduction.kg} kg CO₂ of potential for {inr(recBundle.reduction.cost)} of work.</Note>
        </Card>
      </div>
    </>
  );
};

export const CompanyPage: React.FC = () => {
  const snack = useSnack();
  const { expertMode } = useExpertModeContext();
  const c = useW06Company();
  const rows: Array<[string, string]> = [
    ['Registered name', c.name],
    ['Udyam registration', c.udyam],
    ['GSTIN', c.gst],
    ['Location', c.city],
    ['Industry', c.industry],
    ['Employees', String(c.employees)],
    ['Annual turnover', c.turnover],
    ['What you make', c.product],
  ];
  return (
    <>
      <PageHead page="company" />
      <div className="stack">
        <Card title="Registration" icon="factoryId">
          <Dl rows={rows} />
          <div className="btn-row" style={{ marginTop: 16 }}>
            <button type="button" className="btn ghost" onClick={() => snack('Open the company profile fields from the workflow planner.', 'info')}>
              <Ico name="detail" wrap={false} />Edit details
            </button>
          </div>
        </Card>
        {expertMode ? (
          <Card title="Operations" icon="opsCard">
            <div className="stats">
              <div className="stat"><b>1</b><span>Manufacturing unit</span></div>
              <div className="stat"><b>25</b><span>Employees</span></div>
              <div className="stat"><b>5</b><span>Bills this month</span></div>
              <div className="stat"><b>3</b><span>Assessments</span></div>
            </div>
            <Note>Machinery, materials and commute detail feed Scope 1 and Scope 3. Open the workflow planner to edit them.</Note>
          </Card>
        ) : null}
      </div>
    </>
  );
};

export const OperationsPage: React.FC = () => {
  const snack = useSnack();
  return (
    <>
      <PageHead page="operations" />
      <div className="grid g-hero">
        <Card title="Pune unit 1" icon="factoryId">
          <Figure src={publicAssetUrl('/pune-unit-plan.png')} cap="Demonstration plan of the Pune site. Not a surveyed drawing." />
          <Note>Save the plant picture so bills land on this site, not a generic company total.</Note>
        </Card>
        <Card title="This site" icon="pin">
          {PLANT.map((r) => (
            <ActionRow key={r.k} icon={r.ico} k={r.k} sub={r.sub} v={r.v} />
          ))}
          <div className="btn-row" style={{ marginTop: 16 }}>
            <button type="button" className="btn" onClick={() => snack("Plant picture saved. Upload this month's bill next.", 'success')}>
              Save plant picture
            </button>
          </div>
          <Note>Unit-level Scope 1–3 detail stays in Expert. This screen only names the site the bills belong to.</Note>
        </Card>
      </div>
    </>
  );
};

function DocList({ docs, onCheck }: { docs: typeof import('./seed').DOCS; onCheck: (id: number) => void }) {
  return (
    <>
      {docs.map((d) => (
        <div className="doc" key={d.id}>
          <Ico name="receipt" />
          <div>
            <span className="k">{d.vendor}</span>
            <span className="sub">{d.type} · {d.date}</span>
          </div>
          <span className="amt">{inr(d.amount)}</span>
          <Chip>{d.status}</Chip>
          <button type="button" className="btn sm ghost" onClick={() => onCheck(d.id)}>
            <Ico name="verify" wrap={false} />Check
          </button>
        </div>
      ))}
    </>
  );
}

export const DataPage: React.FC<{ tab: DataTab }> = ({ tab }) => {
  const navigate = useNavigate();
  const snack = useSnack();
  const { expertMode } = useExpertModeContext();
  const x = expertMode;
  const dataTab: DataTab = !x && tab !== 'connectors' ? 'bills' : tab;
  const fileRef = useRef<HTMLInputElement>(null);
  const [over, setOver] = useState(false);
  const [ocrId, setOcrId] = useState<number | null>(null);
  const { data: docs } = useW06Docs();
  const d = docs.find((v) => v.id === ocrId);

  const fire = async (files?: FileList | File[] | null) => {
    const list = files ? Array.from(files) : [];
    if (list.length) {
      try {
        await documentService.uploadDocumentsBulk(list, 'bill');
      } catch {
        /* still show the mockup confirmation so the owner is not blocked */
      }
    }
    snack('Bill uploaded. We are reading it now, which takes about 20 seconds.', 'success');
  };

  const tabs: Array<[DataTab, string]> = x
    ? [['bills', 'Your bills'], ['connectors', 'Data connectors'], ['processed', 'Processed']]
    : [];

  let body: React.ReactNode;
  if (dataTab === 'connectors') {
    body = (
      <Card title="Accounting connectors" icon="connect">
        {CONNECTORS.map((c) => (
          <div className="row" key={c.name}>
            <ConnLogo name={c.name} />
            <div>
              <span className="k">{c.name}</span>
              <span className="sub">{c.sub}</span>
            </div>
            <button type="button" className="btn sm ghost" onClick={() => snack(`${c.name} is not connected yet. We will ask for read-only access.`, 'info')}>
              Connect
            </button>
          </div>
        ))}
        <Note>Connecting a ledger imports vendor invoices automatically, so you upload fewer bills by hand.</Note>
      </Card>
    );
  } else if (dataTab === 'processed') {
    body = (
      <Card title="Processed documents" icon="selected" tail={`${docs.length} of ${docs.length}`}>
        <DocList docs={docs} onCheck={setOcrId} />
      </Card>
    );
  } else {
    body = (
      <>
        <section className="card">
          <h2><Ico name="dropTitle" />Upload a bill</h2>
          <div
            className={`drop${over ? ' over' : ''}`}
            id="drop"
            tabIndex={0}
            role="button"
            aria-label="Choose bills to upload"
            onClick={() => fire()}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                fire();
              }
            }}
            onDragOver={(e) => {
              e.preventDefault();
              setOver(true);
            }}
            onDragLeave={() => setOver(false)}
            onDrop={(e) => {
              e.preventDefault();
              setOver(false);
              fire(e.dataTransfer.files);
            }}
          >
            <Ico name="dropzone" />
            <h3>Drop bills here</h3>
            <p>Electricity, diesel, water, waste or purchase invoices. PDF, JPG or PNG, up to 10 MB each.</p>
            <button
              type="button"
              className="btn ghost"
              onClick={(e) => {
                e.stopPropagation();
                fileRef.current?.click();
              }}
            >
              <Ico name="browse" wrap={false} />Choose files
            </button>
            <input
              ref={fileRef}
              type="file"
              hidden
              multiple
              accept=".pdf,.jpg,.jpeg,.png"
              onChange={(e) => {
                fire(e.target.files);
                e.currentTarget.value = '';
              }}
            />
          </div>
        </section>
        <Card title="Your bills" icon="docsTitle" tail={`${docs.length} bills`}>
          <DocList docs={docs} onCheck={setOcrId} />
        </Card>
      </>
    );
  }

  return (
    <>
      <PageHead page="upload" />
      {tabs.length ? (
        <div className="tabs" role="tablist" aria-label="Data sections">
          {tabs.map(([k, label]) => (
            <button
              key={k}
              type="button"
              role="tab"
              aria-selected={dataTab === k}
              onClick={() => navigate(uploadHref(k))}
            >
              {label}
            </button>
          ))}
        </div>
      ) : null}
      <div className="stack">{body}</div>
      <Modal
        open={d != null}
        title="Check what we read"
        titleId="ocrTitle"
        icon="verify"
        onClose={() => setOcrId(null)}
        foot={(
          <>
            <button type="button" className="btn ghost" onClick={() => setOcrId(null)}>Cancel</button>
            <button
              type="button"
              className="btn"
              onClick={() => {
                snack(`${d?.vendor} confirmed. This month's reading is up to date.`, 'success');
                setOcrId(null);
              }}
            >
              Confirm
            </button>
          </>
        )}
      >
        <div className="fld-grp">
          <label className="fld" htmlFor="ocrVendor">Vendor</label>
          <input type="text" id="ocrVendor" defaultValue={d?.vendor} />
        </div>
        <div className="fld-grp">
          <label className="fld" htmlFor="ocrType">Document type</label>
          <input type="text" id="ocrType" defaultValue={d?.type} />
        </div>
        <div className="fld-grp">
          <label className="fld" htmlFor="ocrDate">Bill date</label>
          <input type="text" id="ocrDate" defaultValue={d?.date} />
        </div>
        <div className="fld-grp">
          <label className="fld" htmlFor="ocrAmt">Amount (GST-exclusive)</label>
          <input type="text" id="ocrAmt" defaultValue={d ? inr(d.amount) : ''} />
        </div>
        {x ? (
          <div className="fld-grp">
            <label className="fld" htmlFor="ocrGst">Vendor GSTIN</label>
            <input type="text" id="ocrGst" defaultValue="" placeholder="Not found on this bill" />
          </div>
        ) : null}
        <Note>Change anything that looks wrong. Your footprint updates when you confirm.</Note>
      </Modal>
    </>
  );
};
