export const CopilotPage: React.FC = () => {
  const snack = useSnack();
  const [q, setQ] = useState('');
  const qs = [
    'Why did my footprint drop 40% since June?',
    'What counts as Scope 3 for a metal parts factory?',
    'What do I need for a BRSR filing?',
  ];
  return (
    <>
      <PageHead page="copilot" />
      <div className="stack">
        <section className="card">
          <h2><Ico name="copilot" />Ask about your data</h2>
          <div className="fld-grp">
            <label className="fld" htmlFor="cpq">Your question</label>
            <textarea id="cpq" value={q} placeholder="Ask anything about your bills, scopes or a framework" onChange={(e) => setQ(e.target.value)} />
          </div>
          <div className="btn-row">
            <button
              type="button"
              className="btn"
              onClick={() => {
                if (!q.trim()) {
                  snack('Type a question first', 'error');
                  document.getElementById('cpq')?.focus();
                  return;
                }
                snack('Looking through your 5 bills and 3 assessments…', 'info');
              }}
            >
              <Ico name="start" wrap={false} />Ask
            </button>
          </div>
          <Note>Answers use your own bills and assessments. Nothing is shared outside your account.</Note>
        </section>
        <Card title="Common questions" icon="info">
          {qs.map((item) => (
            <button
              key={item}
              type="button"
              className="check-btn"
              onClick={() => {
                setQ(item);
                document.getElementById('cpq')?.focus();
              }}
            >
              <span className="mark" aria-hidden="true" style={{ border: 0, color: 'var(--text-3)' }}>
                <Ico name="chevR" wrap={false} />
              </span>
              <div><span className="k">{item}</span></div>
            </button>
          ))}
        </Card>
      </div>
    </>
  );
};

