export const SavingsPage: React.FC = () => {
  const navigate = useNavigate();
  const ui = useW06Ui();
  const { data: recBundle } = useW06Recs();
  const n = ui.recs.size;
  const kg = n
    ? Array.from(ui.recs).reduce((s, id) => {
      const r = recBundle.recs.find((x) => x.id === id);
      return s + (r ? r.reduction : 0);
    }, 0)
    : 0;
  return (
    <>
      <PageHead page="savings" />
      {!n ? (
        <div className="stack">
          <Card title="From your plan" icon="mitigation">
            <Empty
              icon="mitigation"
              title="Nothing selected yet"
              text="Open Reduction ideas and select the work you will do."
              cta="See reduction ideas"
              onCta={() => go(navigate, 'footprint')}
            />
          </Card>
        </div>
      ) : (
        <div className="grid g-hero">
          <Card title="Selected cuts" icon="mitigation">
            <div className="month">
              <b>−{kg} kg</b>
              <span>on the plan · of {recBundle.reduction.kg} kg potential</span>
            </div>
            <Note>This is a plan, not a metered cut.</Note>
          </Card>
          <Card title="Ideas you picked" icon="led">
            {recBundle.recs.filter((r) => ui.recs.has(r.id)).map((r) => (
              <RecRow key={r.id} title={r.title} cost={r.cost} payback={r.payback} reduction={r.reduction} ico={r.ico} />
            ))}
          </Card>
        </div>
      )}
    </>
  );
};

