export const OffsetTrendsPage: React.FC = () => {
  const { data: trendRows } = useW06MarketTrends();
  const maxPrice = trendRows.reduce((m, r) => {
    const n = Number(String(r.v).replace(/[^\d]/g, ''));
    return Math.max(m, n);
  }, 1);
  return (
    <>
      <PageHead page="offsetTrends" />
      <div className="grid g-2">
        <Card title="Market prices" icon="trend">
          <div className="chart">
            {trendRows.map((r) => {
              const n = Number(String(r.v).replace(/[^\d]/g, ''));
              return (
                <div className="bar" key={r.k}>
                  <b>{r.v}</b>
                  <i style={{ height: `${Math.round((n / maxPrice) * 72)}%` }} />
                  <span>{r.k}</span>
                </div>
              );
            })}
          </div>
          <Note>Not a live market feed. Do not treat these rupees as an offer.</Note>
        </Card>
        <Card title="Same months" icon="period">
          {trendRows.map((r) => (
            <ActionRow key={r.k} icon="period" k={r.k} sub={r.sub} v={r.v} />
          ))}
        </Card>
      </div>
    </>
  );
};

