import React, { createContext, useCallback, useContext, useRef, useState } from 'react';
import { Ico } from './Ico';

type Kind = 'info' | 'success' | 'error';

const SnackCtx = createContext<(msg: string, kind?: Kind) => void>(() => undefined);

export const useSnack = () => useContext(SnackCtx);

export const SnackHost: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [msg, setMsg] = useState('');
  const [kind, setKind] = useState<Kind>('info');
  const [show, setShow] = useState(false);
  const timer = useRef<number | undefined>(undefined);

  const snack = useCallback((next: string, k: Kind = 'info') => {
    setMsg(next);
    setKind(k);
    setShow(true);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setShow(false), 3400);
  }, []);

  const ico = kind === 'success' ? 'ok' : kind === 'error' ? 'err' : 'info';

  return (
    <SnackCtx.Provider value={snack}>
      {children}
      <div className={`snackbar${kind === 'success' ? ' success' : kind === 'error' ? ' error' : ''}${show ? ' show' : ''}`} role="status" aria-live="polite">
        <Ico name={ico} wrap={false} />
        <span>{msg}</span>
      </div>
    </SnackCtx.Provider>
  );
};
