import React, { createContext, useContext, useMemo } from 'react';
import { useExpertMode, UseExpertModeResult } from '../hooks/useExpertMode';

const fallbackValue: UseExpertModeResult = {
  expertMode: false,
  simpleMode: true,
  setExpertMode: () => {},
  toggleExpertMode: () => {},
};

const ExpertModeContext = createContext<UseExpertModeResult>(fallbackValue);

interface ExpertModeProviderProps {
  children: React.ReactNode;
}

/** Single shared instance of the Simple/Expert toggle for the whole app. */
export const ExpertModeProvider: React.FC<ExpertModeProviderProps> = ({ children }) => {
  const expertMode = useExpertMode();

  // Memoize on the primitive fields only — the callbacks are stable (useCallback in the hook).
  const value = useMemo(
    () => ({
      expertMode: expertMode.expertMode,
      simpleMode: expertMode.simpleMode,
      setExpertMode: expertMode.setExpertMode,
      toggleExpertMode: expertMode.toggleExpertMode,
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [expertMode.expertMode]
  );

  return <ExpertModeContext.Provider value={value}>{children}</ExpertModeContext.Provider>;
};

/** Read the global Simple/Expert toggle. Safe fallback (Simple, no-op) if provider missing. */
export const useExpertModeContext = (): UseExpertModeResult => useContext(ExpertModeContext);
