import React, { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Ico } from './Ico';
import {
  buildMonthsChart,
  buildCatalog,
  analyticsPinsHref,
  parsePinnedGraphs,
  togglePinnedGraph,
  type AnalyticsCatalogItem,
  type AnalyticsChart,
  type AnalyticsDataParams,
  type AnalyticsPinId,
} from './analyticsGraphs';
import { useW06Score, useW06Assessments, useW06Txns, useW06Recs, useW06Company } from './adapters';
import { BarChart, Card, MeterRow, Note } from './primitives';
import type { WaterfallStep } from '../utils/carbonAnalyticsChartData';

const Fall: React.FC<{ steps: WaterfallStep[] }> = ({ steps }) => {
  const max = Math.max(...steps.map((s) => s.base + s.delta), 1);
  return (
    <div className="fall">
      {steps.map((s) => {
        const width = s.kind === 'reduction' ? (s.base / max) * 100 : (s.delta / max) * 100;
        const signed = s.kind === 'reduction' ? `−${s.delta} kg` : `${s.delta} kg`;
        return (
          <div className="fall-row" key={s.label}>
            <div>
              <span className="k">{s.label}</span>
              <span className="sub">
                {s.kind === 'reduction' ? 'Taken off this month' : s.kind === 'result' ? 'What would remain' : 'August total'}
              </span>
            </div>
            <span className="v">{signed}</span>
            <div className="fall-track" aria-hidden="true">
              <i className={`delta ${s.kind}`} style={{ width: `${width}%` }} />
            </div>
          </div>
        );
      })}
    </div>
  );
};

const ChartBody: React.FC<{ chart: AnalyticsChart }> = ({ chart }) => (
  <>
    {chart.kind === 'bars' && chart.bars && chart.max != null ? (
      <BarChart bars={chart.bars} max={chart.max} axis={chart.axis} />
    ) : null}
    {chart.kind === 'meters' && chart.meters ? (
      <>
        {chart.meters.map((m) => (
          <MeterRow
            key={m.label}
            label={m.label}
            sub={m.sub}
            value={m.value}
            pct={m.pct}
            color="var(--brand-solid)"
            icon={m.icon}
            pctText=""
          />
        ))}
        <p className="axis">{chart.axis}</p>
      </>
    ) : null}
    {chart.kind === 'waterfall' && chart.fall ? (
      <>
        <Fall steps={chart.fall} />
        <p className="axis">{chart.axis}</p>
      </>
    ) : null}
    {chart.columns && chart.rows ? (
      <div className="tbl-wrap">
        <table className="tbl" aria-label={`${chart.title} figures`}>
          <thead>
            <tr>
              {chart.columns.map((col) => (
                <th key={col.label} className={col.num ? 'num' : undefined}>{col.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {chart.rows.map((row) => (
              <tr key={row.id}>
                {row.cells.map((cell, i) => (
                  <td key={`${row.id}-${i}`} className={cell.num ? 'num' : undefined}>{cell.text}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    ) : null}
    {chart.note ? <Note>{chart.note}</Note> : null}
  </>
);

const CatalogRow: React.FC<{
  item: AnalyticsCatalogItem;
  pinned: boolean;
  onToggle: () => void;
}> = ({ item, pinned, onToggle }) => (
  <button type="button" className="check-btn catalog-row" role="option" aria-selected={pinned} onClick={onToggle}>
    <Ico name={item.ico} />
    <div>
      <span className="k">{item.option}</span>
      <span className="sub">{item.blurb}</span>
    </div>
    <span className="v">{pinned ? 'On the board' : 'Add'}</span>
  </button>
);

export const AnalyticsBoard: React.FC = () => {
  const navigate = useNavigate();
  const { search } = useLocation();
  const pinned = parsePinnedGraphs(search);
  const [catalogOpen, setCatalogOpen] = useState(false);

  const { data: score } = useW06Score();
  const { data: assessBundle } = useW06Assessments();
  const { data: txns } = useW06Txns();
  const { data: recBundle } = useW06Recs();
  const company = useW06Company();

  const params: AnalyticsDataParams = useMemo(() => ({
    assessments: assessBundle.rows,
    chartMax: assessBundle.chartMax,
    score,
    txns,
    recs: recBundle.recs,
    company,
  }), [assessBundle, score, txns, recBundle, company]);

  const monthsChart = useMemo(() => buildMonthsChart(params), [params]);
  const catalog = useMemo(() => buildCatalog(params), [params]);

  useEffect(() => {
    if (!catalogOpen) return undefined;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setCatalogOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [catalogOpen]);

  const goPins = (next: AnalyticsPinId[]) => {
    navigate(analyticsPinsHref(next));
  };

  return (
    <>
      <Card title={monthsChart.title} icon={monthsChart.ico}>
        <div className="chart-toolbar">
          <button
            type="button"
            className="btn sm ghost"
            aria-expanded={catalogOpen}
            aria-controls="analytics-chart-catalog"
            onClick={() => setCatalogOpen((open) => !open)}
          >
            <Ico name="analytics" wrap={false} />
            {catalogOpen ? 'Hide chart list' : 'Add a chart'}
          </button>
        </div>
        {catalogOpen ? (
          <div id="analytics-chart-catalog" className="chart-catalog" role="listbox" aria-label="Charts you can add">
            {catalog.map((item) => (
              <CatalogRow
                key={item.id}
                item={item}
                pinned={pinned.includes(item.id)}
                onToggle={() => goPins(togglePinnedGraph(pinned, item.id))}
              />
            ))}
          </div>
        ) : null}
        <ChartBody chart={monthsChart} />
      </Card>
      {pinned.length > 0 ? (
        <div className="grid g-2">
          {pinned.map((id) => {
            const item = catalog.find((g) => g.id === id);
            if (!item) return null;
            return (
              <Card
                key={item.id}
                title={item.title}
                icon={item.ico}
                action={(
                  <button
                    type="button"
                    className="pin-x"
                    aria-label={`Remove ${item.title}`}
                    onClick={() => goPins(togglePinnedGraph(pinned, item.id))}
                  >
                    <Ico name="close" wrap={false} />
                  </button>
                )}
              >
                <ChartBody chart={item} />
              </Card>
            );
          })}
        </div>
      ) : null}
    </>
  );
};
