/* ------------------------------------------------------------------ */
/*  Utilities                                                          */
/* ------------------------------------------------------------------ */

export function unwrap(raw: unknown): Record<string, unknown> | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const rec = raw as Record<string, unknown>;
  if (rec.data && typeof rec.data === 'object') return rec.data as Record<string, unknown>;
  return rec;
}

function num(v: unknown, fallback = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function str(v: unknown, fallback = ''): string {
  return v != null && v !== '' ? String(v) : fallback;
}

function arr(v: unknown): unknown[] {
  return Array.isArray(v) ? v : [];
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function scoreLabel(s: number): string {
  if (s >= 90) return 'Excellent';
  if (s >= 75) return 'Good';
  if (s >= 50) return 'Fair';
  return 'Needs work';
}

function catColor(name: string): string {
  const map: Record<string, string> = {
    energy: 'var(--c-energy)', electricity: 'var(--c-energy)',
    transport: 'var(--c-transport)', transportation: 'var(--c-transport)', fuel: 'var(--c-transport)',
    'raw materials': 'var(--c-materials)', materials: 'var(--c-materials)', manufacturing: 'var(--c-materials)',
    water: 'var(--c-water)',
    waste: 'var(--c-waste)',
  };
  return map[name.toLowerCase()] ?? 'var(--c-materials)';
}

function catIco(name: string): W06IconName {
  const map: Record<string, W06IconName> = {
    energy: 'meter', electricity: 'meter',
    transport: 'truck', transportation: 'truck', fuel: 'truck',
    'raw materials': 'coil', materials: 'coil', manufacturing: 'coil',
    water: 'droplet',
    waste: 'trash',
  };
  return map[name.toLowerCase()] ?? 'coil';
}

type Loaded<T> = { data: T; loading: boolean };

/* ------------------------------------------------------------------ */
/*  useW06Company (existing)                                           */
/* ------------------------------------------------------------------ */

export function useW06Company() {
  const profileQuery = useMsmeProfileQuery();
  const profile = unwrap(profileQuery.data);
  const contact = profile?.contact as { address?: { city?: string; state?: string } } | undefined;
  const cityPart = String(contact?.address?.city || profile?.city || 'Pune');
  const statePart = String(contact?.address?.state || profile?.state || 'Maharashtra');
  return {
    name: String(profile?.companyName || COMPANY.name),
    udyam: String(profile?.udyamRegistrationNumber || COMPANY.udyam),
    gst: String(profile?.gstNumber || COMPANY.gst),
    city: profile?.companyName ? `${cityPart}, ${statePart}` : COMPANY.city,
    industry: String(profile?.industryType || COMPANY.industry),
    employees: Number(profile?.numberOfEmployees || COMPANY.employees),
    turnover: String(profile?.annualTurnover || COMPANY.turnover),
    product: String(profile?.productsServices || profile?.product || COMPANY.product),
  };
}

/* ------------------------------------------------------------------ */
/*  useW06AssessmentFlag (existing)                                     */
/* ------------------------------------------------------------------ */

export function useW06AssessmentFlag() {
  const statsQuery = useMsmeStatsQuery();
  const stats = unwrap(statsQuery.data);
  const carbon = stats?.carbon as {
    totalEmissions?: number;
    totalCO2Emissions?: number;
    currentScore?: number;
  } | undefined;
  const kg = Number(carbon?.totalCO2Emissions || carbon?.totalEmissions || 0);
  const score = Number(carbon?.currentScore || 0);
  if (!statsQuery.isFetched || statsQuery.data == null) return true;
  return kg > 0 || score > 0;
}

/* ------------------------------------------------------------------ */
/*  PHASE 1 — Dashboard & Core Score                                   */
/* ------------------------------------------------------------------ */

export function useW06Score(): Loaded<typeof SCORE> {
  const dashQ = useCarbonDashboardQuery();
  const statsQ = useMsmeStatsQuery();

  return useMemo(() => {
    const dash = unwrap(dashQ.data);
    const stats = unwrap(statsQ.data);
    const carbon = stats?.carbon as Record<string, unknown> | undefined;

    if (!dash && !carbon) return { data: SCORE, loading: dashQ.isLoading || statsQ.isLoading };

    const currentScore = num(carbon?.currentScore ?? dash?.currentScore, SCORE.score);
    const monthTotal = round2(
      num(carbon?.totalCO2Emissions ?? dash?.currentMonthEmissions ?? (dash?.keyData as Record<string, unknown>)?.totalEmissions, SCORE.monthTotal)
    );

    const trend = arr((dash?.monthlyTrend ?? carbon?.monthlyTrend) as unknown)
      .slice(-3)
      .map((t) => num((t as Record<string, unknown>)?.carbonScore ?? (t as Record<string, unknown>)?.co2Emissions));
    const trendArr = trend.length >= 2 ? trend : SCORE.trend;

    const prevKg = trendArr.length >= 2 ? num(trendArr[trendArr.length - 2], SCORE.prevKg) : SCORE.prevKg;
    const deltaKg = round2(Math.abs(prevKg - monthTotal));
    const deltaPct = prevKg > 0 ? String(round2((deltaKg / prevKg) * 100)) : SCORE.deltaPct;

    const firstScore = trendArr.length >= 2 ? trendArr[0] : 0;
    const scoreDelta = currentScore - firstScore;

    return {
      data: {
        score: currentScore,
        label: scoreLabel(currentScore),
        track: monthTotal <= prevKg ? 'On track' : 'Off track',
        delta: scoreDelta > 0 ? `+${scoreDelta} pts since Q1` : `${scoreDelta} pts since Q1`,
        trend: trendArr,
        monthTotal,
        tco2e: (monthTotal / 1000).toFixed(2),
        prevKg,
        deltaKg,
        deltaPct,
      },
      loading: false,
    };
  }, [dashQ.data, dashQ.isLoading, statsQ.data, statsQ.isLoading]);
}

export function useW06Scopes(): Loaded<ScopeRow[]> {
  const dashQ = useCarbonDashboardQuery();

  return useMemo(() => {
    const dash = unwrap(dashQ.data);
    const esg = dash?.esgScopes as Record<string, Record<string, unknown>> | undefined;
    if (!esg) return { data: SCOPES, loading: dashQ.isLoading };

    const s1 = num(esg.scope1?.total);
    const s2 = num(esg.scope2?.total);
    const s3 = num(esg.scope3?.total);
    const total = s1 + s2 + s3 || 1;

    const rows: ScopeRow[] = [
      { ...SCOPES[0], val: round2(s1), pct: Math.round((s1 / total) * 100) },
      { ...SCOPES[1], val: round2(s2), pct: Math.round((s2 / total) * 100) },
      { ...SCOPES[2], val: round2(s3), pct: Math.round((s3 / total) * 100) },
    ];
    return { data: rows, loading: false };
  }, [dashQ.data, dashQ.isLoading]);
}

export function useW06Categories(): Loaded<{ cats: typeof CATEGORIES; max: number; hotspot: typeof HOTSPOT }> {
  const dashQ = useCarbonDashboardQuery();

  return useMemo(() => {
    const dash = unwrap(dashQ.data);
    const raw = dash?.categoryBreakdown as Record<string, Record<string, unknown>> | undefined;
    if (!raw) return { data: { cats: CATEGORIES, max: CAT_MAX, hotspot: HOTSPOT }, loading: dashQ.isLoading };

    const cats = Object.entries(raw)
      .map(([k, v]) => ({
        k,
        v: round2(num(v?.co2Emissions ?? v?.co2)),
        color: catColor(k),
        ico: catIco(k),
      }))
      .filter((c) => c.v > 0)
      .sort((a, b) => b.v - a.v);

    const max = cats.length > 0 ? cats[0].v : CAT_MAX;
    const top = cats[0];
    const hotspot = top
      ? { k: top.k, v: top.v, vendor: str((raw[top.k] as Record<string, unknown>)?.topVendor, HOTSPOT.vendor) }
      : HOTSPOT;

    return { data: { cats: cats.length > 0 ? cats : CATEGORIES, max, hotspot }, loading: false };
  }, [dashQ.data, dashQ.isLoading]);
}

export function useW06Assessments(): Loaded<{ rows: typeof ASSESSMENTS; chartMax: number }> {
  const q = useCarbonAssessmentByPeriodQuery('monthly');

  return useMemo(() => {
    const raw = unwrap(q.data);
    const buckets = arr(raw?.periodBuckets ?? raw?.assessments ?? raw?.data);
    if (buckets.length === 0) return { data: { rows: ASSESSMENTS, chartMax: CHART_MAX }, loading: q.isLoading };

    const rows = buckets.slice(-6).map((b) => {
      const rec = b as Record<string, unknown>;
      const label = str(rec.periodLabel ?? rec.month ?? rec.label, '');
      const score = num(rec.carbonScore ?? rec.score);
      const kg = round2(num(rec.totalCO2Emissions ?? rec.co2Emissions ?? rec.kg));
      const txns = num(rec.totalTransactions ?? rec.transactionCount ?? rec.txns);
      return { label, score, kg, txns };
    });

    const chartMax = rows.reduce((m, r) => Math.max(m, r.kg), 0) || CHART_MAX;
    return { data: { rows, chartMax }, loading: false };
  }, [q.data, q.isLoading]);
}

export function useW06Recs(): Loaded<{ recs: typeof RECS; reduction: typeof REDUCTION }> {
  const dashQ = useCarbonDashboardQuery();

  return useMemo(() => {
    const dash = unwrap(dashQ.data);
    const rawRecs = arr(dash?.topRecommendations);
    if (rawRecs.length === 0) return { data: { recs: RECS, reduction: REDUCTION }, loading: dashQ.isLoading };

    const recs = rawRecs.slice(0, 5).map((r, i) => {
      const rec = r as Record<string, unknown>;
      return {
        id: num(rec.id ?? rec._id, i + 1),
        title: str(rec.title),
        priority: str(rec.priority, 'medium'),
        reduction: round2(num(rec.potentialCO2Reduction ?? rec.co2Reduction)),
        cost: num(rec.estimatedCost ?? rec.cost),
        payback: str(rec.paybackPeriod ?? rec.payback, '—'),
        ico: catIco(str(rec.category)) as W06IconName,
      };
    });

    const totalKg = round2(recs.reduce((s, r) => s + r.reduction, 0));
    const totalCost = recs.reduce((s, r) => s + r.cost, 0);

    return {
      data: {
        recs: recs.length > 0 ? recs : RECS,
        reduction: { kg: totalKg || REDUCTION.kg, cost: totalCost || REDUCTION.cost },
      },
      loading: false,
    };
  }, [dashQ.data, dashQ.isLoading]);
}

export function useW06Setup(): Loaded<typeof SETUP> {
  const profileQ = useMsmeProfileQuery();
  const statsQ = useMsmeStatsQuery();

  return useMemo(() => {
    const profile = unwrap(profileQ.data);
    const stats = unwrap(statsQ.data);
    if (!profile && !stats) return { data: SETUP, loading: profileQ.isLoading || statsQ.isLoading };

    const hasProfile = Boolean(profile?.companyName && profile?.gstNumber);
    const carbon = stats?.carbon as Record<string, unknown> | undefined;
    const docBulk = stats?.documentBulkUpload as Record<string, unknown> | undefined;
    const docCount = num(docBulk?.totalDocuments);
    const assessCount = num(carbon?.totalAssessments ?? stats?.assessments);
    const hasTarget = num(carbon?.reductionTargetPct) > 0;

    const steps = [
      { ...SETUP[0], done: hasProfile },
      { ...SETUP[1], done: docCount > 0 },
      { ...SETUP[2], done: assessCount > 0, sub: docCount > 0 ? `${docCount} bill${docCount !== 1 ? 's' : ''} read and counted` : SETUP[2].sub },
      { ...SETUP[3], done: hasTarget },
    ];

    return { data: steps, loading: false };
  }, [profileQ.data, profileQ.isLoading, statsQ.data, statsQ.isLoading]);
}

export function useW06Readiness(): Loaded<typeof READINESS> {
  const q = useComplianceOverviewQuery();

  return useMemo(() => {
    const data = unwrap(q.data);
    if (!data) return { data: READINESS, loading: q.isLoading };

    const scores = data.moduleScores as Record<string, number | null> | undefined;
    const overall = num(data.indiaOverallReadinessScore);
    const exportScore = num(data.exportOverallReadinessScore);

    const rows: typeof READINESS = [];
    if (scores) {
      if (scores.brsrCore != null) rows.push({ name: 'BRSR', pct: num(scores.brsrCore) });
      if (scores.isoAssurance != null) rows.push({ name: 'ISO 14064', pct: num(scores.isoAssurance) });
      if (scores.cbam != null) rows.push({ name: 'CBAM', pct: num(scores.cbam) });
      if (scores.pat != null) rows.push({ name: 'PAT', pct: num(scores.pat) });
      if (scores.sbti != null) rows.push({ name: 'SBTi', pct: num(scores.sbti) });
    }

    if (rows.length === 0 && (overall > 0 || exportScore > 0)) {
      rows.push({ name: 'India compliance', pct: overall });
      if (exportScore > 0) rows.push({ name: 'Export compliance', pct: exportScore });
    }

    return { data: rows.length > 0 ? rows : READINESS, loading: false };
  }, [q.data, q.isLoading]);
}

