export function useW06Txns(): Loaded<typeof TXNS> {
  const q = useTransactionsQuery({ limit: 50 });

  return useMemo(() => {
    const raw = unwrap(q.data);
    const list = arr(raw?.transactions ?? raw?.data);
    if (list.length === 0) return { data: TXNS, loading: q.isLoading };

    const rows = list.map((t, i) => {
      const r = t as Record<string, unknown>;
      const calcDetails = r.calculationDetails as Record<string, unknown> | undefined;
      return {
        id: num(r.id ?? r._id, i + 1),
        vendor: str(r.vendor ?? r.merchantName),
        source: str(r.category ?? r.source),
        type: str(r.type ?? r.subCategory ?? r.category),
        amount: num(r.amount),
        emissions: round2(num(r.co2Emissions ?? r.emissions ?? calcDetails?.co2Emissions)),
        factor: round2(num(r.emissionFactor ?? calcDetails?.emissionFactor)),
        scope: str(r.scope ?? calcDetails?.scope, 'Scope 3'),
        method: str(r.calculationMethod ?? calcDetails?.calculationMethod, 'spend-based'),
        status: str(r.status, 'Processed'),
      };
    });

    return { data: rows, loading: false };
  }, [q.data, q.isLoading]);
}

