export function useW06TwinZones(): Loaded<typeof TWIN_ZONES> {
  const { data: catData, loading } = useW06Categories();

  return useMemo(() => {
    if (loading) return { data: TWIN_ZONES, loading: true };

    const total = catData.cats.reduce((s, c) => s + c.v, 0) || 1;
    const zones = catData.cats.map((c) => {
      const seed = TWIN_ZONES.find((z) => z.ico === c.ico);
      return {
        k: seed?.k ?? `${c.k} zone`,
        sub: seed?.sub ?? c.k,
        v: `${c.v.toFixed(2)} kg`,
        kg: c.v,
        pct: Math.round((c.v / total) * 100),
        ico: c.ico as W06IconName,
        color: c.color,
      };
    });

    return { data: zones.length > 0 ? zones : TWIN_ZONES, loading: false };
  }, [catData, loading]);
}

export function useW06Docs(): Loaded<typeof DOCS> {
  const q = useDocumentsQuery({ limit: 50 });

  return useMemo(() => {
    const raw = q.data as Record<string, unknown> | null | undefined;
    const docs = arr(raw?.documents);
    if (docs.length === 0) return { data: DOCS, loading: q.isLoading };

    const rows = docs.map((d, i) => {
      const r = d as Record<string, unknown>;
      const extracted = r.extractedData as Record<string, unknown> | undefined;
      return {
        id: num(r.id ?? r._id, i + 1),
        vendor: str(extracted?.vendor ?? r.vendor ?? r.originalName),
        type: str(r.documentType ?? extracted?.category, 'Bill'),
        date: str(extracted?.date ?? r.createdAt),
        amount: num(extracted?.amount ?? r.amount),
        gstin: str(extracted?.gstin),
        status: str(r.status, 'Processed'),
      };
    });

    return { data: rows, loading: false };
  }, [q.data, q.isLoading]);
}

/* ------------------------------------------------------------------ */
/*  PHASE 3 — Compliance, Finance, Offsets, Savings, Reports, Billing */
/* ------------------------------------------------------------------ */

function mapStatus(s: unknown): string {
  const v = str(s).toLowerCase();
  if (v === 'complete' || v === 'completed' || v === 'done' || v === 'ready') return 'Ready';
  if (v === 'in_progress' || v === 'in-progress' || v === 'partial') return 'In progress';
  if (v === 'not_applicable' || v === 'not-applicable') return 'Not applicable';
  if (v === 'not_started' || v === 'not-started') return 'Not started';
  return 'Pending';
}

export function useW06ComplianceIndia(): Loaded<typeof COMPLIANCE_INDIA> {
  const q = useComplianceOverviewQuery();

  return useMemo(() => {
    const data = unwrap(q.data);
    const ir = data?.indiaReadiness as Record<string, unknown> | undefined;
    if (!ir) return { data: COMPLIANCE_INDIA, loading: q.isLoading };

    const map: Array<{ key: string; name: string; sub: string; ico: W06IconName }> = [
      { key: 'brsrCore', name: 'BRSR', sub: 'Business responsibility report', ico: 'reports' },
      { key: 'isoAssurance', name: 'ISO 14064', sub: 'GHG inventory assurance', ico: 'factoryId' },
      { key: 'patIntensity', name: 'PAT', sub: 'Perform, achieve, trade', ico: 'targets' },
      { key: 'epr', name: 'EPR', sub: 'Extended producer responsibility', ico: 'trash' },
      { key: 'sbti', name: 'SBTi', sub: 'Science-based targets', ico: 'trend' },
      { key: 'zedCertification', name: 'ZED', sub: 'Zero defect zero effect', ico: 'selected' },
    ];

    const rows = map.map((m) => ({
      name: m.name,
      sub: m.sub,
      status: mapStatus(ir[m.key]),
      ico: m.ico as W06IconName,
    }));

    return { data: rows, loading: false };
  }, [q.data, q.isLoading]);
}

