export function useW06GapCheck(): Loaded<typeof GAP_CHECK> {
  const q = useComplianceOverviewQuery();

  return useMemo(() => {
    const data = unwrap(q.data);
    const gapDetails = data?.moduleGapDetails as Record<string, Record<string, unknown>> | undefined;
    if (!gapDetails) return { data: GAP_CHECK, loading: q.isLoading };

    const rows: typeof GAP_CHECK = [];
    let id = 1;
    for (const [moduleKey, detail] of Object.entries(gapDetails)) {
      const gaps = arr(detail?.gaps ?? detail?.items);
      for (const g of gaps) {
        const r = g as Record<string, unknown>;
        rows.push({
          id: id++,
          title: str(r.label ?? r.title ?? `${moduleKey} gap`),
          sub: str(r.description ?? r.hint),
          done: Boolean(r.resolved ?? r.done ?? r.passed),
        });
      }
    }

    return { data: rows.length > 0 ? rows : GAP_CHECK, loading: false };
  }, [q.data, q.isLoading]);
}

export function useW06Finance(): Loaded<typeof SCHEMES> {
  const q = useFinanceOverviewQuery();

  return useMemo(() => {
    const data = unwrap(q.data);
    const options = arr(data?.options);
    if (options.length === 0) return { data: SCHEMES, loading: q.isLoading };

    const rows = options
      .filter((o) => {
        const r = o as Record<string, unknown>;
        return str(r.id) !== 'gift_applications' && str(r.id) !== 'points_rewards';
      })
      .map((o) => {
        const r = o as Record<string, unknown>;
        const icoMap: Record<string, W06IconName> = {
          green_loans: 'loans',
          gift_schemes: 'schemes',
          adeetie: 'hub',
        };
        return {
          name: str(r.title),
          sub: str(r.description),
          ico: (icoMap[str(r.id)] ?? 'finance') as W06IconName,
          path: str(r.path, `/${str(r.id).replace(/_/g, '-')}`),
        };
      });

    return { data: rows.length > 0 ? rows : SCHEMES, loading: false };
  }, [q.data, q.isLoading]);
}

