export function useW06Savings(): Loaded<{ totalKg: number; pct: number; implemented: number }> {
  const q = useCarbonSavingsQuery();

  return useMemo(() => {
    const raw = unwrap(q.data);
    const savings = raw?.savings as Record<string, unknown> | undefined;
    if (!savings) return { data: { totalKg: 0, pct: 0, implemented: 0 }, loading: q.isLoading };

    return {
      data: {
        totalKg: round2(num(savings.totalSavings)),
        pct: round2(num(savings.savingsPercentage)),
        implemented: num(savings.implementedRecommendations),
      },
      loading: false,
    };
  }, [q.data, q.isLoading]);
}

export function useW06Reports(): Loaded<typeof REPORTS> {
  const { data: readiness, loading } = useW06Readiness();

  return useMemo(() => {
    if (loading) return { data: REPORTS, loading: true };

    const rows = readiness.map((r) => {
      const base = REPORTS.find((rp) => rp.k.toLowerCase().includes(r.name.toLowerCase()));
      return {
        k: base?.k ?? r.name,
        sub: base?.sub ?? `${r.name} report`,
        status: `${r.pct}% ready`,
        ico: (base?.ico ?? 'reports') as W06IconName,
      };
    });

    return { data: rows.length > 0 ? rows : REPORTS, loading: false };
  }, [readiness, loading]);
}

export function useW06BuyerReqs(): Loaded<typeof BUYER_REQS> {
  return useMemo(() => ({ data: BUYER_REQS, loading: false }), []);
}

export function useW06Billing(): Loaded<{ applicable: boolean; status: string; plan: string }> {
  const q = useBillingStatusQuery();

  return useMemo(() => {
    const data = unwrap(q.data);
    if (!data) return { data: { applicable: false, status: 'N/A', plan: 'Free' }, loading: q.isLoading };

    const profile = data.profile as Record<string, unknown> | undefined;
    return {
      data: {
        applicable: Boolean(data.billingApplicable),
        status: str(profile?.status, 'inactive'),
        plan: str(profile?.selectedPlanId, 'Free'),
      },
      loading: false,
    };
  }, [q.data, q.isLoading]);
}
