export type W06IconName = keyof typeof W06_PATHS;

const SVG = (inner: string) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" dangerouslySetInnerHTML={{ __html: inner }} />
);

/** `wrap` matches mockup `ciIco()`; `wrap={false}` matches `ciSvg()` (raw SVG, parent CSS sets size). */
export const Ico: React.FC<{ name: W06IconName | string; color?: string; wrap?: boolean }> = ({
  name,
  color,
  wrap = true,
}) => {
  const inner = W06_PATHS[name as W06IconName];
  if (!inner) return null;
  const svg = SVG(inner);
  if (!wrap) return svg;
  return <span className="ico" aria-hidden="true" style={color ? { color } : undefined}>{svg}</span>;
};

export function connIco(name: string): W06IconName | '' {
  const n = String(name).toLowerCase();
  if (n.includes('tally')) return 'tally';
  if (n.includes('zoho')) return 'zoho';
  if (n.includes('quick')) return 'qbooks';
  if (n.includes('clear')) return 'cleartax';
  if (n.includes('upi')) return 'upi';
  return '';
}

/** Official vendor mark when we have one; stroke pictogram otherwise. */
export const ConnLogo: React.FC<{ name: string }> = ({ name }) => {
  const src = connectorLogoSrc(name);
  if (!src) {
    const fallback = connIco(name);
    return <Ico name={fallback || 'connect'} />;
  }
  return (
    <span className="conn-logo" aria-hidden="true">
      <img src={src} alt="" />
    </span>
  );
};
