import { useCallback, useEffect, useState } from 'react';

/** localStorage key for the global Simple/Expert UI toggle. Default is Simple (false). */
export const EXPERT_MODE_STORAGE_KEY = 'ci_expert_mode';

const readStoredExpertMode = (): boolean => {
  if (typeof window === 'undefined') {
    return false;
  }
  return window.localStorage.getItem(EXPERT_MODE_STORAGE_KEY) === 'true';
};

export type UseExpertModeResult = {
  expertMode: boolean;
  simpleMode: boolean;
  setExpertMode: (next: boolean) => void;
  toggleExpertMode: () => void;
};

/**
 * Global Simple/Expert UI toggle. Owns the `ci_expert_mode` localStorage key.
 * Default is Simple (expertMode = false). Header.tsx is the only writer; screens read.
 */
export const useExpertMode = (): UseExpertModeResult => {
  const [expertMode, setExpertModeState] = useState<boolean>(readStoredExpertMode);

  useEffect(() => {
    window.localStorage.setItem(EXPERT_MODE_STORAGE_KEY, String(expertMode));
  }, [expertMode]);

  const setExpertMode = useCallback((next: boolean) => {
    setExpertModeState(next);
  }, []);

  const toggleExpertMode = useCallback(() => {
    setExpertModeState((current) => !current);
  }, []);

  return {
    expertMode,
    simpleMode: !expertMode,
    setExpertMode,
    toggleExpertMode,
  };
};
