import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Ico } from './Ico';
import { PlantPlan } from './plant';
import { useSnack } from './Snack';
import { useW06Ui } from './context';
import { useExpertModeContext } from '../context/ExpertModeContext';
import { AnalyticsBoard } from './AnalyticsBoard';
import { footprintHref, type FpTab } from './paths';
import {
  useW06Score,
  useW06Scopes,
  useW06Categories,
  useW06Recs,
  useW06Txns,
  useW06TwinZones,
  useW06Forecast,
} from './adapters';
import {
  ActionRow,
  BarChart,
  Card,
  Chip,
  Empty,
  MeterRow,
  Modal,
  Note,
  PageHead,
  RecRow,
  ScopeCard,
  inr,
} from './primitives';

function Overview() {
  const navigate = useNavigate();
  const { expertMode } = useExpertModeContext();
  const x = expertMode;
  const { data: score } = useW06Score();
  const { data: scopes } = useW06Scopes();
  const { data: catBundle } = useW06Categories();
  return (
    <>
      <div className="grid g-hero">
        <Card title="This month" icon="monthKg">
          <div className="score-line">
            <span className="score">{score.monthTotal}</span>
            <span className="score-of">kg CO₂</span>
          </div>
          <div className="month">
            <b>−{score.deltaKg}</b>
            <span>kg vs previous · −{score.deltaPct}% · {score.prevKg} kg then</span>
          </div>
          {x ? <p className="meta-line">{score.tco2e} tCO₂e · spend-based · ISO 14064 aligned</p> : null}
        </Card>
        <Card title="Biggest source" icon="hotspot">
          <div className="month" style={{ marginTop: 0, paddingTop: 0, borderTop: 0 }}>
            <b>{catBundle.hotspot.v}</b>
            <span>kg from {catBundle.hotspot.k}</span>
          </div>
          <p style={{ marginTop: 8, fontSize: 13.5, color: 'var(--text-2)' }}>
            {catBundle.hotspot.vendor} purchases are the biggest source this month. Sourcing closer can cut costs.
          </p>
          <div className="btn-row" style={{ marginTop: 16 }}>
            <button type="button" className="btn ghost" onClick={() => navigate(footprintHref('ideas'))}>
              <Ico name="mitigation" wrap={false} />See reduction ideas
            </button>
          </div>
        </Card>
      </div>
      <div>
        <div className="block-head">
          <Ico name="scopeCard" />
          <h2>By scope</h2>
        </div>
        <div className="grid g-3">
          {scopes.map((s) => (
            <ScopeCard key={s.tag} scope={s} />
          ))}
        </div>
        {x ? <Note>Scope 2 reported location-based. Scope 3 covers purchased goods, water and waste only.</Note> : null}
      </div>
      <Card title="By category" icon="catCard">
        {catBundle.cats.map((c) => (
          <MeterRow
            key={c.k}
            label={c.k}
            value={`${c.v.toFixed(2)} kg`}
            pct={Math.round((c.v / catBundle.max) * 100)}
            color={c.color}
            icon={c.ico}
            pctText=""
          />
        ))}
        <Note>Bar length compares each category with the largest, not with the month total.</Note>
      </Card>
    </>
  );
}

function TxnSection() {
  const snack = useSnack();
  const { expertMode } = useExpertModeContext();
  const x = expertMode;
  const ui = useW06Ui();
  const { data: txns } = useW06Txns();
  const { data: catBundle } = useW06Categories();
  const [txnId, setTxnId] = useState<number | null>(null);
  const all = txns.filter(
    (t) =>
      (ui.txnSource === 'all' || t.source === ui.txnSource) &&
      `${t.vendor} ${t.type} ${t.source}`.toLowerCase().includes(ui.txnSearch.toLowerCase())
  );
  const pages = Math.max(1, Math.ceil(all.length / ui.txnSize));
  const page = Math.min(Math.max(1, ui.txnPage), pages);
  const slice = all.slice((page - 1) * ui.txnSize, page * ui.txnSize);
  const sources = ['all', ...catBundle.cats.map((c) => c.k)];
  const t = txns.find((v) => v.id === txnId);
  const toolbar = (
    <div className="toolbar">
      <div className="search">
        <Ico name="search" />
        <input
          type="text"
          id="txnSearch"
          value={ui.txnSearch}
          placeholder="Search vendor or type"
          aria-label="Search bills"
          onChange={(e) => {
            ui.setTxnSearch(e.target.value);
            ui.setTxnPage(1);
          }}
        />
      </div>
      <select
        id="txnSource"
        aria-label="Filter by source"
        value={ui.txnSource}
        onChange={(e) => {
          ui.setTxnSource(e.target.value);
          ui.setTxnPage(1);
        }}
      >
        {sources.map((s) => (
          <option key={s} value={s}>{s === 'all' ? 'All sources' : s}</option>
        ))}
      </select>
      <button type="button" className="btn ghost sm" onClick={() => snack('CSV of 5 bills downloaded', 'success')}>
        <Ico name="csv" wrap={false} />Export CSV
      </button>
    </div>
  );

  const rows: Array<[string, string]> = t
    ? [
      ['Vendor', t.vendor],
      ['Source', t.type],
      ['Amount (GST-exclusive)', inr(t.amount)],
      ['Emissions', `${t.emissions.toFixed(2)} kg CO₂`],
      ['Status', t.status],
      ...(x
        ? [
          ['Scope', t.scope],
          ['Emission factor', `${t.factor} kg CO₂ per ₹`],
          ['Method', t.method],
          ['Data quality', 'Tier 2 · spend-based'],
        ] as Array<[string, string]>
        : []),
    ]
    : [];

  return (
    <>
      <Card title="Bills & activity" icon="txnTitle" tail={all.length ? `${all.length} bills` : undefined}>
        {toolbar}
        {!all.length ? (
          <Empty icon="search" title="Nothing matches that filter" text="Clear the search box or pick a different source to see your five bills again." />
        ) : (
          <>
            <div className="tbl-wrap">
              <table className="tbl">
                <thead>
                  <tr>
                    <th>Vendor</th>
                    <th>Source</th>
                    {x ? <th>Scope</th> : null}
                    {x ? <th className="num">Factor</th> : null}
                    <th className="num">Amount</th>
                    <th className="num">kg CO₂</th>
                    <th>Status</th>
                    <th><span className="sr">Detail</span></th>
                  </tr>
                </thead>
                <tbody>
                  {slice.map((row) => (
                    <tr key={row.id}>
                      <td className="vend">{row.vendor}</td>
                      <td>{row.type}</td>
                      {x ? <td>{row.scope}</td> : null}
                      {x ? <td className="num">{row.factor}</td> : null}
                      <td className="num">{inr(row.amount)}</td>
                      <td className="num">{row.emissions.toFixed(2)}</td>
                      <td><Chip>{row.status}</Chip></td>
                      <td className="num">
                        <button type="button" className="btn sm ghost" onClick={() => setTxnId(row.id)}>
                          <Ico name="detail" wrap={false} />Detail
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="pager">
              <span>
                {(page - 1) * ui.txnSize + 1}–{Math.min(page * ui.txnSize, all.length)} of {all.length}
              </span>
              <button type="button" aria-label="Previous page" disabled={page === 1} onClick={() => ui.setTxnPage(page - 1)}>
                <Ico name="chevL" wrap={false} />
              </button>
              <button type="button" aria-label="Next page" disabled={page === pages} onClick={() => ui.setTxnPage(page + 1)}>
                <Ico name="chevR" wrap={false} />
              </button>
            </div>
          </>
        )}
      </Card>
      <Modal
        open={t != null}
        title={t?.vendor || ''}
        titleId="txnTitle"
        icon="detail"
        onClose={() => setTxnId(null)}
        foot={<button type="button" className="btn ghost" onClick={() => setTxnId(null)}>Close</button>}
      >
        <dl className="dl">
          {rows.map(([dt, dd]) => (
            <React.Fragment key={dt}>
              <dt>{dt}</dt>
              <dd>{dd}</dd>
            </React.Fragment>
          ))}
        </dl>
        {x ? (
          <Note>Spend-based factors carry more uncertainty than metered readings. Connect your meter to move this to Tier 1.</Note>
        ) : null}
      </Modal>
    </>
  );
}

export const FootprintPage: React.FC<{ tab: FpTab }> = ({ tab }) => {
  const navigate = useNavigate();
  const snack = useSnack();
  const { expertMode } = useExpertModeContext();
  const ui = useW06Ui();
  const fpTab: FpTab = !expertMode && tab === 'analytics' ? 'overview' : tab;
  const tabs: Array<[FpTab, string]> = [
    ['overview', 'Overview'],
    ['bills', 'Bills & activity'],
    ...(expertMode ? [['analytics', 'Analytics'] as [FpTab, string]] : []),
    ['ideas', 'Reduction ideas'],
  ];

  const { data: recBundle } = useW06Recs();

  let body: React.ReactNode;
  if (fpTab === 'bills') body = <TxnSection />;
  else if (fpTab === 'analytics') {
    body = <AnalyticsBoard />;
  } else if (fpTab === 'ideas') {
    body = (
      <Card title="Reduction ideas" icon="mitigation">
        {recBundle.recs.map((r) => (
          <RecRow
            key={r.id}
            title={r.title}
            cost={r.cost}
            payback={r.payback}
            reduction={r.reduction}
            ico={r.ico}
            selectable
            selected={ui.recs.has(r.id)}
            onSelect={() => {
              const on = ui.recs.has(r.id);
              ui.toggleRec(r.id);
              snack(on ? 'Removed from your reduction plan' : 'Added to your reduction plan', 'success');
            }}
          />
        ))}
        <Note>Selected: {ui.recs.size} of {recBundle.recs.length} · full potential {recBundle.reduction.kg} kg CO₂ for {inr(recBundle.reduction.cost)}</Note>
      </Card>
    );
  } else body = <Overview />;

  return (
    <>
      <PageHead page="footprint" />
      <div className="tabs" role="tablist" aria-label="Footprint sections">
        {tabs.map(([k, label]) => (
          <button key={k} type="button" role="tab" aria-selected={fpTab === k} onClick={() => navigate(footprintHref(k))}>
            {label}
          </button>
        ))}
      </div>
      <div className="stack">{body}</div>
    </>
  );
};

export const CarbonTwinPage: React.FC = () => {
  const snack = useSnack();
  const { data: zones } = useW06TwinZones();
  const hotZone = zones[0];
  return (
    <>
      <PageHead page="carbonTwin" />
      <div className="stack">
        <div className="grid g-hero">
          <Card title="This month on the floor" icon="twin">
            <PlantPlan />
            <Note>The top row scales by kilograms. Water and waste sit on the floor strip so every bay keeps its own name. The outlined bay is the hotspot.</Note>
          </Card>
          <Card title="Hottest zone" icon="hotspot">
            <div className="month">
              <b>{hotZone.v}</b>
              <span>{hotZone.k} · {hotZone.sub}</span>
            </div>
            <ActionRow icon={hotZone.ico} color={hotZone.color} k={hotZone.k} sub={hotZone.sub} v={hotZone.v} />
            <Note>{hotZone.pct}% of this month sits on one zone. Invite the vendor for a primary factor.</Note>
          </Card>
        </div>
        <Card title="Zones this month" icon="catCard">
          {zones.map((z) => (
            <ActionRow key={z.k} icon={z.ico} color={z.color} k={z.k} sub={z.sub} v={z.v} />
          ))}
        </Card>
        <Card title="Ask a supplier" icon="mail">
          <div className="row">
            <Ico name="mail" />
            <div>
              <span className="k">Steel Mart</span>
              <span className="sub">Invite them to send a primary factor instead of a spend estimate</span>
            </div>
            <button type="button" className="btn sm" onClick={() => snack('Invite queued for Steel Mart. Nothing is shared outside your account.', 'info')}>
              Invite
            </button>
          </div>
        </Card>
      </div>
    </>
  );
};

export const ForecastingPage: React.FC = () => {
  const { data: forecast } = useW06Forecast();
  const forecastMax = forecast.reduce((m, r) => Math.max(m, r.kg), 0) || 68.8;
  return (
    <>
      <PageHead page="forecasting" />
      <div className="grid g-2">
        <Card title="Next months" icon="trend">
          <BarChart
            bars={forecast.map((r) => ({ label: r.label, kg: r.kg, forecast: r.kind === 'Forecast' }))}
            max={forecastMax}
            axis="Solid bars are actual months. Lighter bars are a demonstration forecast, not a commitment."
          />
        </Card>
        <Card title="Actual then forecast" icon="period">
          <div className="tbl-wrap">
            <table className="tbl">
              <thead>
                <tr>
                  <th>Month</th>
                  <th>Kind</th>
                  <th className="num">kg CO₂</th>
                </tr>
              </thead>
              <tbody>
                {forecast.map((r) => (
                  <tr key={r.label}>
                    <td>{r.label}</td>
                    <td>{r.kind}</td>
                    <td className="num">{r.kg}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <Note>Forecast months follow recent trends. They are not a filed number.</Note>
        </Card>
      </div>
    </>
  );
};
