import { publicAssetUrl } from '../constants/brand';

const NAME_TO_FILE: Array<[RegExp, string]> = [
  [/tally/i, 'tally'],
  [/zoho/i, 'zoho'],
  [/quick/i, 'quickbooks'],
  [/clear/i, 'clear'],
  [/upi/i, 'upi'],
];

export function connectorLogoSrc(name: string): string | undefined {
  const hit = NAME_TO_FILE.find(([re]) => re.test(String(name)));
  return hit ? publicAssetUrl(`/assets/connectors/${hit[1]}.svg`) : undefined;
}
