import React from 'react';
import { useLocation } from 'react-router-dom';
import { resolvePage } from './paths';
import { CompanyPage, DataPage, HomePage, OperationsPage } from './pagesHome';
import { CarbonTwinPage, FootprintPage, ForecastingPage } from './pagesFootprint';
import {
  AdeetiePage,
  BillingPage06,
  BuyerAuditPage,
  CompliancePage,
  CopilotPage,
  DataPrivacyPage06,
  ExportTrackPage,
  FinancePage,
  GiftAppsPage,
  GiftSchemesPage,
  GreenLoansPage,
  HelpPage,
  IndiaPage,
  InformationPage06,
  OffsetHistoryPage,
  OffsetProjectsPage,
  OffsetTrendsPage,
  OffsetWalletPage,
  OffsetsPage,
  ReportingPage,
  SavingsPage,
  SettingsPage06,
  TargetsChartsPage,
  TargetsPage,
} from './pagesRest';

const WorkspacePage: React.FC = () => {
  const { pathname, search } = useLocation();
  const { page, dataTab, fpTab } = resolvePage(pathname, search);

  switch (page) {
    case 'dashboard':
      return <HomePage />;
    case 'company':
      return <CompanyPage />;
    case 'operations':
      return <OperationsPage />;
    case 'upload':
      return <DataPage tab={dataTab} />;
    case 'footprint':
      return <FootprintPage tab={fpTab} />;
    case 'carbonTwin':
      return <CarbonTwinPage />;
    case 'forecasting':
      return <ForecastingPage />;
    case 'compliance':
      return <CompliancePage />;
    case 'india':
      return <IndiaPage />;
    case 'exportTrack':
      return <ExportTrackPage />;
    case 'buyerAudit':
      return <BuyerAuditPage />;
    case 'reporting':
      return <ReportingPage />;
    case 'targets':
      return <TargetsPage />;
    case 'targetsCharts':
      return <TargetsChartsPage />;
    case 'savings':
      return <SavingsPage />;
    case 'offsets':
      return <OffsetsPage />;
    case 'offsetProjects':
      return <OffsetProjectsPage />;
    case 'offsetWallet':
      return <OffsetWalletPage />;
    case 'offsetTrends':
      return <OffsetTrendsPage />;
    case 'offsetHistory':
      return <OffsetHistoryPage />;
    case 'finance':
      return <FinancePage />;
    case 'adeetie':
      return <AdeetiePage />;
    case 'greenLoans':
      return <GreenLoansPage />;
    case 'giftSchemes':
      return <GiftSchemesPage />;
    case 'giftApps':
      return <GiftAppsPage />;
    case 'copilot':
      return <CopilotPage />;
    case 'settings':
      return <SettingsPage06 />;
    case 'help':
      return <HelpPage />;
    case 'information':
      return <InformationPage06 />;
    case 'billing':
      return <BillingPage06 />;
    case 'dataPrivacy':
      return <DataPrivacyPage06 />;
    default:
      return <HomePage />;
  }
};

export default WorkspacePage;
