import React from 'react';
import { Ico, type W06IconName } from './Ico';
import { TWIN_ZONES } from './seed';

type Zone = (typeof TWIN_ZONES)[number];

type Packed = { z: Zone; value: number; color: string; ico: W06IconName };

function bayInner(p: Packed, total: number, dens: string) {
  const pct = Math.round((p.value / total) * 100);
  const name = p.z.k.replace(/ bay$/i, '');
  return (
    <>
      <div className="bay-head">
        {dens === 'full' || dens === 'strip' ? <Ico name={p.ico} /> : null}
        <b>{name}</b>
      </div>
      <span className="qty">{`${p.value.toFixed(2)} kg`}</span>
      <span className="bay-pct">{pct}%</span>
    </>
  );
}

export const PlantPlan: React.FC<{ zones?: Zone[] }> = ({ zones = TWIN_ZONES }) => {
  const live = zones.filter((z) => z.kg > 0);
  const total = live.reduce((s, z) => s + z.kg, 0) || 1;
  const packed: Packed[] = live.map((z) => ({ z, value: z.kg, color: z.color, ico: z.ico }));
  const FLOOR = 0.08;
  let main = packed.filter((p) => p.value / total >= FLOOR);
  let rest = packed.filter((p) => p.value / total < FLOOR);
  if (!main.length) {
    const sorted = packed.slice().sort((a, b) => b.value - a.value);
    main = sorted.slice(0, Math.min(3, sorted.length));
    rest = sorted.slice(main.length);
  }

  return (
    <div className="plan" role="img" aria-label="Plant bays sized by this month kilograms">
      <div className="plan-main">
        {main.map((p, i) => (
          <div
            key={p.z.k}
            className={`bay full${i === 0 ? ' hot' : ''}`}
            style={{ flex: `${p.value} 1 0`, background: p.color }}
            title={`${p.z.k.replace(/ bay$/i, '')} · ${p.value.toFixed(2)} kg · ${Math.round((p.value / total) * 100)}%`}
          >
            {bayInner(p, total, 'full')}
          </div>
        ))}
      </div>
      {rest.length ? (
        <div className="plan-floor">
          {rest.map((p) => (
            <div
              key={p.z.k}
              className="bay strip"
              style={{ flex: `${p.value} 1 0`, background: p.color }}
              title={`${p.z.k.replace(/ bay$/i, '')} · ${p.value.toFixed(2)} kg · ${Math.round((p.value / total) * 100)}%`}
            >
              {bayInner(p, total, 'strip')}
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
};
