import React, { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import './w06.css';
import { Ico } from './Ico';
import { NAV_ICON, PAGES } from './seed';
import {
  BOTTOM_NAV,
  PAGE_HREF,
  childActive,
  childHref,
  findTopic,
  navTopics,
  resolvePage,
  topicDefaultActive,
  type NavTopic,
  type PageKey,
} from './paths';
import { SnackHost, useSnack } from './Snack';
import { W06UiProvider } from './context';
import { useW06AssessmentFlag, useW06Company } from './adapters';
import { BRAND_DASHBOARD_MARK_SRC, BRAND_LOGO_SRC } from '../constants/brand';
import { useExpertModeContext } from '../context/ExpertModeContext';
import { useThemeMode } from '../context/ThemeModeContext';
import { SUBSCRIPTION_PLANS_ENABLED } from '../constants/subscriptionPlans';

function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return 'GT';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
}

const ShellInner: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const snack = useSnack();
  const { simpleMode, setExpertMode, expertMode } = useExpertModeContext();
  const { isDarkMode, toggleThemeMode } = useThemeMode();
  const [moreOpen, setMoreOpen] = useState(false);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  const { page, dataTab, fpTab } = resolvePage(location.pathname, location.search);
  const hasAssessment = useW06AssessmentFlag();
  const hasExportIntent = true;
  const company = useW06Company();
  const companyName = company.name;
  const gst = company.gst;
  const udyam = company.udyam;
  const city = company.city.split(',')[0] || 'Pune';
  const period = 'August 2026';

  const { primary, secondary } = useMemo(
    () => navTopics(expertMode, hasAssessment, hasExportIntent),
    [expertMode, hasAssessment, hasExportIntent]
  );

  const allowed = useMemo(() => {
    const out = new Set<PageKey>();
    [...primary, ...secondary].forEach((t) => {
      out.add(t.page);
      t.children.forEach((c) => out.add(c.page));
    });
    return out;
  }, [primary, secondary]);

  useEffect(() => {
    if (!allowed.has(page) && page !== 'dashboard') {
      navigate('/dashboard', { replace: true });
    }
  }, [allowed, page, navigate]);

  useEffect(() => {
    const t = findTopic(page, expertMode, hasAssessment, hasExportIntent);
    if (!t) return;
    setExpanded((prev) => {
      const next: Record<string, boolean> = { ...prev };
      [...primary, ...secondary].forEach((p) => {
        if (p.children.length) next[p.page] = p.page === t.page;
      });
      return next;
    });
  }, [page, expertMode, hasAssessment, hasExportIntent, primary, secondary]);

  const go = (key: PageKey, opts?: { parent?: boolean; tab?: string; fp?: string }) => {
    if (opts?.parent && key === 'upload') {
      navigate('/document-upload');
      return;
    }
    if (opts?.parent && key === 'footprint') {
      navigate('/carbon-footprint?section=overview');
      return;
    }
    if (key === 'billing' && !SUBSCRIPTION_PLANS_ENABLED) {
      snack('Billing is switched off for this workspace.', 'info');
    }
    navigate(PAGE_HREF[key]);
  };

  const setMode = (mode: 'simple' | 'expert') => {
    setExpertMode(mode === 'expert');
    snack(
      mode === 'expert'
        ? 'Expert view on. Methodology, factors and framework detail are shown.'
        : 'Simple view on. Auditor detail is hidden.',
      'info'
    );
    if (mode === 'simple' && fpTab === 'analytics') {
      navigate('/carbon-footprint?section=overview');
    }
  };

  const renderTopic = (t: NavTopic) => {
    const kids = t.children;
    const onPath = topicDefaultActive(t, page, dataTab, fpTab) || kids.some((c) => childActive(c, page, dataTab, fpTab)) || kids.some((c) => c.page === page);
    const expandedOn = expanded[t.page] === true || (expanded[t.page] !== false && onPath);
    const parentActive = topicDefaultActive(t, page, dataTab, fpTab);

    if (!kids.length) {
      return (
        <button
          key={t.page}
          type="button"
          className={`nav-item${page === t.page ? ' active' : ''}`}
          aria-current={page === t.page ? 'page' : undefined}
          onClick={() => go(t.page)}
        >
          <Ico name={NAV_ICON[t.page]} wrap={false} />
          <span>{PAGES[t.page].label}</span>
        </button>
      );
    }

    return (
      <div className="nav-group" key={t.page}>
        <div className="nav-parent">
          <button
            type="button"
            className={`nav-item${parentActive ? ' active' : ''}`}
            aria-current={parentActive ? 'page' : undefined}
            onClick={() => go(t.page, { parent: true })}
          >
            <Ico name={NAV_ICON[t.page]} wrap={false} />
            <span>{PAGES[t.page].label}</span>
          </button>
          <button
            type="button"
            className="nav-chev"
            aria-expanded={expandedOn}
            aria-label={`${expandedOn ? 'Collapse' : 'Expand'} ${PAGES[t.page].label}`}
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              setExpanded((prev) => ({ ...prev, [t.page]: !expandedOn }));
            }}
          >
            <Ico name="chevR" wrap={false} />
          </button>
        </div>
        {expandedOn ? (
          <div className="nav-children">
            {kids.map((c) => {
              const active = childActive(c, page, dataTab, fpTab);
              return (
                <button
                  key={`${c.page}-${c.label}`}
                  type="button"
                  className={`nav-item child${active ? ' active' : ''}`}
                  aria-current={active ? 'page' : undefined}
                  onClick={() => navigate(childHref(c))}
                >
                  <Ico name={c.ico} wrap={false} />
                  <span>{c.label}</span>
                </button>
              );
            })}
          </div>
        ) : null}
      </div>
    );
  };

  const topic = findTopic(page, expertMode, hasAssessment, hasExportIntent);
  const crumbs = (() => {
    if (page === 'dashboard') return <span className="now">Home</span>;
    const leaf = PAGES[page];
    return (
      <>
        <button type="button" onClick={() => go('dashboard')}>Home</button>
        <span className="sep" aria-hidden="true">/</span>
        {topic && topic.page !== page ? (
          <>
            <button type="button" onClick={() => go(topic.page, { parent: true })}>{PAGES[topic.page].label}</button>
            <span className="sep" aria-hidden="true">/</span>
          </>
        ) : null}
        <span className="now">{leaf.label}</span>
      </>
    );
  })();

  const sheetItems = (() => {
    const seen = new Set<string>();
    const bottom = new Set(BOTTOM_NAV.filter((b) => b.page !== 'more').map((b) => b.page as string));
    const items: Array<{ key: string; label: string; href: string; ico: string }> = [];
    const addPage = (key: PageKey) => {
      if (bottom.has(key) || seen.has(key) || !PAGES[key]) return;
      seen.add(key);
      items.push({ key, label: PAGES[key].label, href: PAGE_HREF[key], ico: NAV_ICON[key] });
    };
    [...primary, ...secondary].forEach((t) => {
      addPage(t.page);
      t.children.forEach((c) => {
        const href = childHref(c);
        if (seen.has(href) || bottom.has(c.page)) return;
        seen.add(href);
        items.push({ key: href, label: c.label, href, ico: c.ico });
      });
    });
    return items;
  })();

  return (
    <>
      <a className="skip" href="#main">Skip to content</a>
      <div className="app">
        <aside className="sidebar" aria-label="Primary navigation">
          <div className="sb-brand">
            <img src={BRAND_LOGO_SRC} alt="" />
            <div className="wm">
              <b>sust<span className="ai">ai</span>now</b>
              <span>Carbon Intelligence</span>
            </div>
          </div>
          <nav className="sb-nav" aria-label="Primary">
            {primary.map(renderTopic)}
            <div className="nav-sec">{secondary.map(renderTopic)}</div>
          </nav>
          <div className="sb-foot">
            <b>{companyName}</b>
            GST {gst}<br />
            {udyam}<br />
            {city} · {period}
          </div>
        </aside>

        <div className="col">
          <header className="topbar">
            <div className="top-mark">
              <img src={BRAND_DASHBOARD_MARK_SRC} alt="Sustainow Carbon Intelligence" />
            </div>
            <nav className="crumbs" aria-label="Breadcrumb">{crumbs}</nav>
            <div className="top-end">
              <div className="seg" role="group" aria-label="Detail level">
                <button type="button" aria-pressed={simpleMode} onClick={() => setMode('simple')}>Simple</button>
                <button type="button" aria-pressed={expertMode} onClick={() => setMode('expert')}>Expert</button>
              </div>
              <button
                className="icon-btn"
                type="button"
                data-theme-toggle=""
                aria-pressed={isDarkMode}
                aria-label={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
                onClick={toggleThemeMode}
              >
                <svg className="i-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M20.5 14.6A8.6 8.6 0 0 1 9.4 3.5a8.6 8.6 0 1 0 11.1 11.1z" /></svg>
                <svg className="i-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4" /><path d="M12 2.6v2.4M12 19v2.4M4.4 4.4l1.7 1.7M17.9 17.9l1.7 1.7M2.6 12H5M19 12h2.4M4.4 19.6l1.7-1.7M17.9 6.1l1.7-1.7" /></svg>
              </button>
              <button className="avatar" type="button" aria-label={`${companyName} account`} onClick={() => snack(`Signed in as ${companyName}`, 'info')}>
                <i>{initials(companyName)}</i>
              </button>
            </div>
          </header>

          <main className="content" id="main">
            <div className="container">
              <section className="page active">{children}</section>
            </div>
          </main>
        </div>
      </div>

      <nav className="bottom-nav" aria-label="Mobile">
        <div className="bn-inner">
          {BOTTOM_NAV.map((n) => {
            if (n.page === 'more') {
              return (
                <button key="more" type="button" onClick={() => setMoreOpen(true)}>
                  <Ico name="more" wrap={false} />
                  <span>More</span>
                </button>
              );
            }
            const on = n.page === page || (topic && topic.page === n.page);
            return (
              <button
                key={n.page}
                type="button"
                className={on ? 'active' : ''}
                aria-current={on ? 'page' : undefined}
                onClick={() => go(n.page as PageKey, { parent: true })}
              >
                <Ico name={n.picto} wrap={false} />
                <span>{n.label}</span>
              </button>
            );
          })}
        </div>
      </nav>

      <div className={`sheet${moreOpen ? ' open' : ''}`} aria-hidden={!moreOpen}>
        <div className="backdrop" onClick={() => setMoreOpen(false)} />
        <div className="panel" role="dialog" aria-modal="true" aria-label="More">
          <div className="m-head">
            <h3>More</h3>
            <button className="x" type="button" aria-label="Close" onClick={() => setMoreOpen(false)}>
              <Ico name="close" wrap={false} />
            </button>
          </div>
          <div>
            {sheetItems.map((item) => (
              <button
                key={item.key}
                type="button"
                className="sheet-item"
                onClick={() => {
                  setMoreOpen(false);
                  navigate(item.href);
                }}
              >
                <Ico name={item.ico} wrap={false} />
                <span>{item.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </>
  );
};

const Workspace06NewImprovedUiLayout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isDarkMode } = useThemeMode();
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);
  return (
    <div className="w06" data-theme={isDarkMode ? 'dark' : 'light'}>
      <W06UiProvider>
        <SnackHost>
          <ShellInner>{children}</ShellInner>
        </SnackHost>
      </W06UiProvider>
    </div>
  );
};

export default Workspace06NewImprovedUiLayout;
