import React, { useEffect, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Container, Box } from '@mui/material';
import Header from './components/Header';
import Workspace06NewImprovedUiLayout from './workspace06NewImprovedUi/Shell';
import WorkspacePage from './workspace06NewImprovedUi/WorkspacePage';
import { shouldShowAppSidebar, isInternalPortalPath } from './constants/appNavigation';
import { MobileNavProvider, useMobileNav } from './context/MobileNavContext';
import ErrorBoundary from './components/ErrorBoundary';
import MSMERegistration from './components/MSMERegistration';
import PreLoginDashboard from './components/PreLoginDashboard';
import PricingRouteGate from './components/PricingRouteGate';
import ProtectedRoute from './components/ProtectedRoute';
import RequireMSME from './components/RequireMSME';
import RequireWorkflowPlanner from './components/RequireWorkflowPlanner';
import UserLogin from './components/UserLogin';
import EnterpriseAppRoutes from './components/enterprise/EnterpriseAppRoutes';
import { RegistrationProvider, useRegistration } from './context/RegistrationContext';
import { OrganizationProvider } from './context/OrganizationContext';
import UserRegister from './components/UserRegister';
import ForgotPassword from './components/ForgotPassword';
import ResetPassword from './components/ResetPassword';
import AboutUsPage from './components/AboutUsPage';
import InsightsPage from './components/InsightsPage';
import InsightArticlePage from './components/InsightArticlePage';
import WhyCarbonIntelligencePage from './components/WhyCarbonIntelligencePage';
import PublicCarbonPassportPage from './components/compliance/PublicCarbonPassportPage';
import SupplierInvitePage from './components/compliance/SupplierInvitePage';
import {
  BillingCancellationPolicyPage,
  BillingPrivacyPolicyPage,
  BillingRefundPolicyPage,
  BillingTermsAndConditionsPage,
} from './components/billing/BillingLegalPages';
import {
  HelpCenterPage,
  PrivacyPolicyPage,
  TermsOfServicePage,
} from './components/StaticPages';
import AdminDashboard from './components/admin/AdminDashboard';
import AdminSystemHealthDashboard from './components/admin/AdminSystemHealthDashboard';
import MSMEDetailView from './components/admin/MSMEDetailView';
import AdminRoute from './components/admin/AdminRoute';
import AdminWriteRoute from './components/admin/AdminWriteRoute';
import SupportDashboard from './components/support/SupportDashboard';
import SupportMSMEView from './components/support/SupportMSMEView';
import SupportRoute from './components/support/SupportRoute';
import PartnerIntegrationsAdmin from './components/admin/PartnerIntegrationsAdmin';
import BlogArticlesAdmin from './components/admin/BlogArticlesAdmin';
import BenchmarkReports from './components/BenchmarkReports';
import AutomatedTestingDashboard from './components/AutomatedTestingDashboard';
import PartnersPage from './components/partners/PartnersPage';
import PartnerApiDocumentationPage from './components/partners/PartnerApiDocumentationPage';
import PartnerDashboard from './components/partner/PartnerDashboard';
import PartnerRoute from './components/partner/PartnerRoute';
import NotFoundPage from './components/NotFoundPage';
import NavigationRouteProgress from './components/NavigationRouteProgress';
import RouteLoadingGate from './components/RouteLoadingGate';
import PageInformationBanner from './components/PageInformationBanner';
import { APP_CONTENT_GUTTER } from './constants/appShellLayout';
import { resolveDocumentTitle } from './utils/routePageMeta';

interface RouteWrapperProps {
  children: React.ReactElement;
}

const OnboardedRoute: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>
      <RequireWorkflowPlanner>{children}</RequireWorkflowPlanner>
    </RequireMSME>
  </ProtectedRoute>
);

const RequireMSMEProfile: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>{children}</RequireMSME>
  </ProtectedRoute>
);

function AppRoutes() {
  const location = useLocation();
  const { isRegistered, isLoggingOut } = useRegistration();
  const { closeMobileNav } = useMobileNav();
  const showSidebar = !isLoggingOut && shouldShowAppSidebar(location.pathname, isRegistered);
  const hideGlobalChrome = isInternalPortalPath(location.pathname);

  useEffect(() => {
    closeMobileNav();
  }, [closeMobileNav, location.pathname, location.search]);

  useEffect(() => {
    if (typeof window.scrollTo !== 'function') {
      return;
    }
    try {
      window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
    } catch {
      window.scrollTo(0, 0);
    }
  }, [location.pathname, location.search]);

  useEffect(() => {
    document.title = resolveDocumentTitle(location.pathname || '/');
  }, [location.pathname]);

  const header = !hideGlobalChrome ? <Header /> : null;

  const workspaceTree = (
              <ErrorBoundary resetKeys={[location.pathname, location.search]}>
              <Suspense fallback={<RouteLoadingGate message="Loading page..." minHeight="40vh" />}>
              <Routes>
              <Route
                path="/msme-registration"
                element={(
                  <ProtectedRoute>
                    <MSMERegistration />
                  </ProtectedRoute>
                )}
              />
              <Route path="/" element={<PreLoginDashboard />} />
              <Route path="/pricing" element={<PricingRouteGate />} />
              <Route path="/login" element={<UserLogin />} />
              <Route path="/register" element={<UserRegister />} />
              <Route path="/enterprise/*" element={<EnterpriseAppRoutes />} />
              <Route path="/forgot-password" element={<ForgotPassword />} />
              <Route path="/reset-password" element={<ResetPassword />} />
              <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
              <Route path="/terms-of-service" element={<TermsOfServicePage />} />
              <Route path="/help" element={isRegistered ? <WorkspacePage /> : <HelpCenterPage />} />
              <Route path="/about-us" element={<AboutUsPage />} />
              <Route path="/insights" element={<InsightsPage />} />
              <Route path="/insights/:slug" element={<InsightArticlePage />} />
              <Route path="/why-carbon-intelligence" element={<WhyCarbonIntelligencePage />} />
              <Route path="/why-sci" element={<Navigate to="/why-carbon-intelligence" replace />} />
              <Route path="/why-ci" element={<Navigate to="/why-carbon-intelligence" replace />} />
              <Route path="/partners" element={<PartnersPage />} />
              <Route path="/carbon-passport/:token" element={<PublicCarbonPassportPage />} />
              <Route path="/supplier-invite/:token" element={<SupplierInvitePage />} />
              <Route path="/partners/api-documentation" element={<PartnerApiDocumentationPage />} />
              <Route path="/developers" element={<Navigate to="/partners" replace />} />
              <Route path="/partner" element={<Navigate to="/login" replace />} />
              <Route path="/partner/login" element={<Navigate to="/login" replace />} />
              <Route
                path="/partner/dashboard"
                element={(
                  <PartnerRoute>
                    <PartnerDashboard />
                  </PartnerRoute>
                )}
              />
              <Route path="/admin" element={<Navigate to="/login" replace />} />
              <Route path="/admin/login" element={<Navigate to="/login" replace />} />
              <Route
                path="/admin/dashboard"
                element={(
                  <AdminRoute>
                    <AdminDashboard />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/msme/:id"
                element={(
                  <AdminRoute>
                    <MSMEDetailView />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/integrations"
                element={(
                  <AdminRoute>
                    <PartnerIntegrationsAdmin />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/blog-articles"
                element={(
                  <AdminRoute>
                    <BlogArticlesAdmin />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/ocr-benchmarks"
                element={(
                  <AdminRoute>
                    <AdminWriteRoute>
                      <BenchmarkReports />
                    </AdminWriteRoute>
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/ocr-automation"
                element={(
                  <AdminRoute>
                    <AdminWriteRoute>
                      <AutomatedTestingDashboard />
                    </AdminWriteRoute>
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/system-health"
                element={(
                  <AdminRoute>
                    <AdminWriteRoute>
                      <AdminSystemHealthDashboard />
                    </AdminWriteRoute>
                  </AdminRoute>
                )}
              />
              <Route
                path="/support/dashboard"
                element={(
                  <SupportRoute>
                    <SupportDashboard />
                  </SupportRoute>
                )}
              />
              <Route
                path="/support/msme/:id"
                element={(
                  <SupportRoute>
                    <SupportMSMEView />
                  </SupportRoute>
                )}
              />
              <Route path="/support" element={<Navigate to="/support/dashboard" replace />} />
              <Route
                path="/dashboard"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route path="/msme-list" element={<Navigate to="/dashboard" replace />} />
              <Route
                path="/msme-profile"
                element={(
                  <RequireMSMEProfile>
                    <WorkspacePage />
                  </RequireMSMEProfile>
                )}
              />
              <Route
                path="/msme-profile/workflow-planner"
                element={<Navigate to="/operations" replace />}
              />
              <Route
                path="/operations"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-twin"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-footprint"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-marketplace"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-credits"
                element={(
                  <Navigate to="/carbon-marketplace" replace />
                )}
              />
              <Route
                path="/carbon-trading"
                element={(
                  <Navigate to="/carbon-marketplace" replace />
                )}
              />
              <Route
                path="/carbon-savings"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-schemes"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/finance"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/adeetie"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/new"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:schemeId/new"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:id/edit"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/recommendations"
                element={<Navigate to="/carbon-footprint?section=recommendations" replace />}
              />
              <Route
                path="/incentives"
                element={<Navigate to="/finance" replace />}
              />
              <Route
                path="/compliance"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/india"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/buyer-audit"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/export"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/product-pcf"
                element={(
                  <OnboardedRoute>
                    <Navigate to="/compliance" replace />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/geotagged-capture"
                element={(
                  <OnboardedRoute>
                    <Navigate to="/compliance" replace />
                  </OnboardedRoute>
                )}
              />
              <Route path="/reports" element={<Navigate to="/reporting" replace />} />
              <Route
                path="/reporting"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/green-loans"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-forecasting"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/ai-advisor"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-copilot"
                element={<Navigate to="/ai-advisor" replace />}
              />
              <Route
                path="/emissions-reduction-targets"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/documents"
                element={<Navigate to="/document-upload" replace />}
              />
              <Route
                path="/document-upload"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/data"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/document-management"
                element={(
                  <Navigate to="/data" replace />
                )}
              />
              <Route
                path="/data-privacy"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing/terms-and-conditions"
                element={(
                  <OnboardedRoute>
                    <BillingTermsAndConditionsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing/privacy-policy"
                element={(
                  <OnboardedRoute>
                    <BillingPrivacyPolicyPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing/refund-policy"
                element={(
                  <OnboardedRoute>
                    <BillingRefundPolicyPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing/cancellation-policy"
                element={(
                  <OnboardedRoute>
                    <BillingCancellationPolicyPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/manufacturing-workflow"
                element={(
                  <Navigate to="/operations" replace />
                )}
              />
              <Route
                path="/settings"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/information"
                element={(
                  <OnboardedRoute>
                    <WorkspacePage />
                  </OnboardedRoute>
                )}
              />
                <Route path="*" element={<NotFoundPage />} />
              </Routes>
              </Suspense>
              </ErrorBoundary>
  );

  if (showSidebar) {
    return (
      <>
        <NavigationRouteProgress />
        <Workspace06NewImprovedUiLayout>{workspaceTree}</Workspace06NewImprovedUiLayout>
      </>
    );
  }

  return (
    <Box
      sx={{
        flexGrow: 1,
        minHeight: '100vh',
        backgroundColor: 'background.default',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <NavigationRouteProgress />
      {header}
      <Box sx={{ display: 'flex', flex: 1, minHeight: 0 }}>
        <Container
          disableGutters
          maxWidth={false}
          sx={{
            px: APP_CONTENT_GUTTER,
            pt: { xs: '16px', md: '24px' },
            pb: '16px',
            maxWidth: 1280,
            flex: 1,
            minWidth: 0,
          }}
        >
          <Box id="main-content" component="main" tabIndex={-1}>
            {!hideGlobalChrome && !isLoggingOut ? <PageInformationBanner /> : null}
            {workspaceTree}
          </Box>
        </Container>
      </Box>
    </Box>
  );
}

function App() {
  return (
    <RegistrationProvider>
      <OrganizationProvider>
        <MobileNavProvider>
          <AppRoutes />
        </MobileNavProvider>
      </OrganizationProvider>
    </RegistrationProvider>
  );
}

export default App;
