import { useQuery } from '@tanstack/react-query';
import { queryKeys } from '../constants/queryKeys';
import ApiService from '../services/api';
import documentService from '../services/documentService';

const W06_STALE_MS = 3 * 60_000;

export function useCarbonAssessmentByPeriodQuery(
  groupBy: 'monthly' | 'annual' | 'weekly' | 'datewise' = 'monthly',
  enabled = true
) {
  return useQuery({
    queryKey: ['carbon', 'assessment-by-period', groupBy] as const,
    queryFn: async () => {
      try {
        return await ApiService.getCarbonAssessmentByPeriod({ groupBy, limit: 12 });
      } catch {
        return null;
      }
    },
    enabled,
    staleTime: W06_STALE_MS,
    refetchOnWindowFocus: false,
  });
}

