import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { GAP_CHECK } from './seed';
import ApiService from '../services/api';
import { useReductionTargetQuery } from '../hooks/queries/useDashboardQueries';

type W06Ui = {
  recs: Set<number>;
  toggleRec: (id: number) => void;
  gaps: Set<number>;
  toggleGap: (id: number) => void;
  target: number;
  setTarget: (n: number) => void;
  commitTarget: () => void;
  unitPrice: number;
  setUnitPrice: (n: number) => void;
  commitUnitPrice: () => void;
  txnSearch: string;
  setTxnSearch: (s: string) => void;
  txnSource: string;
  setTxnSource: (s: string) => void;
  txnPage: number;
  setTxnPage: (n: number | ((p: number) => number)) => void;
  txnSize: number;
};

const Ctx = createContext<W06Ui | null>(null);

export function useW06Ui(): W06Ui {
  const v = useContext(Ctx);
  if (!v) throw new Error('useW06Ui must be inside W06UiProvider');
  return v;
}

function numFrom(raw: unknown, keys: string[]): number | null {
  if (!raw || typeof raw !== 'object') return null;
  const rec = raw as Record<string, unknown>;
  const data = rec.data && typeof rec.data === 'object' ? (rec.data as Record<string, unknown>) : rec;
  for (const k of keys) {
    const n = Number(data[k]);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

export const W06UiProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const targetQuery = useReductionTargetQuery();
  const [recs, setRecs] = useState<Set<number>>(() => new Set());
  const [gaps, setGaps] = useState<Set<number>>(() => new Set(GAP_CHECK.filter((g) => g.done).map((g) => g.id)));
  const [target, setTarget] = useState(20);
  const [unitPrice, setUnitPrice] = useState(250);
  const [txnSearch, setTxnSearch] = useState('');
  const [txnSource, setTxnSource] = useState('all');
  const [txnPage, setTxnPage] = useState(1);
  const txnSize = 3;

  useEffect(() => {
    const n = numFrom(targetQuery.data, ['reductionTargetPct', 'target']);
    if (n != null) setTarget(n);
  }, [targetQuery.data]);

  useEffect(() => {
    let alive = true;
    ApiService.getMaintenanceUnitPrice()
      .then((raw) => {
        const n = numFrom(raw, ['maintenanceUnitPriceInr', 'unitPrice']);
        if (alive && n != null) setUnitPrice(n);
      })
      .catch(() => undefined);
    return () => {
      alive = false;
    };
  }, []);

  const toggleRec = useCallback((id: number) => {
    setRecs((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const toggleGap = useCallback((id: number) => {
    setGaps((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const commitTarget = useCallback(() => {
    ApiService.updateReductionTarget(target).catch(() => undefined);
  }, [target]);

  const commitUnitPrice = useCallback(() => {
    ApiService.updateMaintenanceUnitPrice(unitPrice).catch(() => undefined);
  }, [unitPrice]);

  const value = useMemo(
    () => ({
      recs,
      toggleRec,
      gaps,
      toggleGap,
      target,
      setTarget,
      commitTarget,
      unitPrice,
      setUnitPrice,
      commitUnitPrice,
      txnSearch,
      setTxnSearch,
      txnSource,
      setTxnSource,
      txnPage,
      setTxnPage,
      txnSize,
    }),
    [
      recs, toggleRec, gaps, toggleGap, target, commitTarget, unitPrice, commitUnitPrice,
      txnSearch, txnSource, txnPage, txnSize,
    ]
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
};
