import type { W06IconName } from './Ico';
import { footprintHref } from './paths';
import { ASSESSMENTS, CHART_MAX, COMPANY, RECS, SCORE, TXNS } from './seed';
import { buildReductionWaterfall, type WaterfallStep } from '../utils/carbonAnalyticsChartData';

export type AnalyticsPinId = 'score' | 'bills' | 'kg-per-bill' | 'invoices' | 'intensity' | 'plan';

export type AnalyticsBar = { label: string; kg: number; color?: string };

export type AnalyticsMeter = {
  label: string;
  sub?: string;
  value: string;
  pct: number;
  raw: number;
  icon?: W06IconName;
};

export type AnalyticsChart = {
  id: 'months' | AnalyticsPinId;
  title: string;
  ico: W06IconName;
  axis: string;
  kind: 'bars' | 'meters' | 'waterfall';
  max?: number;
  bars?: AnalyticsBar[];
  columns?: Array<{ label: string; num?: boolean }>;
  rows?: Array<{ id: string; cells: Array<{ text: string; num?: boolean }> }>;
  meters?: AnalyticsMeter[];
  fall?: WaterfallStep[];
  note?: string;
};

export type AnalyticsCatalogItem = AnalyticsChart & {
  id: AnalyticsPinId;
  option: string;
  blurb: string;
};

const PIN_IDS: AnalyticsPinId[] = ['score', 'bills', 'kg-per-bill', 'invoices', 'intensity', 'plan'];

const isPinId = (id: string): id is AnalyticsPinId => (PIN_IDS as string[]).includes(id);

const kgPerBill = (kg: number, txns: number) => txns > 0 ? Math.round((kg / txns) * 100) / 100 : 0;

/* ------------------------------------------------------------------ */
/*  Data-param types                                                   */
/* ------------------------------------------------------------------ */

export type AnalyticsDataParams = {
  assessments: Array<{ label: string; score: number; kg: number; txns: number }>;
  chartMax: number;
  score: { monthTotal: number; deltaKg: number; deltaPct: string };
  txns: Array<{ id: number; vendor: string; type: string; emissions: number; factor: number }>;
  recs: Array<{ id: number; title: string; reduction: number }>;
  company: { employees: number };
};

/* ------------------------------------------------------------------ */
/*  Build charts from live data                                        */
/* ------------------------------------------------------------------ */

function buildMonthsChart(p: AnalyticsDataParams): AnalyticsChart {
  return {
    id: 'months',
    title: 'Emissions by month',
    ico: 'analytics',
    kind: 'bars',
    axis: `kg CO₂ per month · ${p.score.deltaKg} kg lower than previous (−${p.score.deltaPct}%)`,
    max: p.chartMax,
    bars: p.assessments.map((a) => ({ label: a.label, kg: a.kg })),
    columns: [
      { label: 'Month' },
      { label: 'Score', num: true },
      { label: 'kg CO₂', num: true },
      { label: 'Bills', num: true },
    ],
    rows: p.assessments.map((a) => ({
      id: a.label,
      cells: [
        { text: a.label },
        { text: String(a.score), num: true },
        { text: String(a.kg), num: true },
        { text: String(a.txns), num: true },
      ],
    })),
  };
}

function buildCatalog(p: AnalyticsDataParams): AnalyticsCatalogItem[] {
  const scoreMax = Math.max(...p.assessments.map((a) => a.score), 1);
  const billCountMax = Math.max(...p.assessments.map((a) => a.txns), 1);
  const perBillRows = p.assessments.map((a) => ({ label: a.label, kg: kgPerBill(a.kg, a.txns) }));
  const perBillMax = Math.max(...perBillRows.map((r) => r.kg), 1);
  const invoiceMax = Math.max(...p.txns.map((t) => t.emissions), 1);
  const factorMax = Math.max(...p.txns.map((t) => t.factor), 1);

  return [
    {
      id: 'score',
      option: 'Carbon score',
      blurb: 'How the 0–100 score moved month to month.',
      title: 'Carbon score by month',
      ico: 'score',
      kind: 'bars',
      axis: `Higher is better. Latest is ${p.assessments[p.assessments.length - 1]?.score ?? '—'}.`,
      max: scoreMax,
      bars: p.assessments.map((a) => ({ label: a.label, kg: a.score })),
    },
    {
      id: 'bills',
      option: 'Bills counted',
      blurb: "How many invoices sat in each month's reading.",
      title: 'Bills counted by month',
      ico: 'txnTitle',
      kind: 'bars',
      axis: 'Number of invoices counted per month.',
      max: billCountMax,
      bars: p.assessments.map((a) => ({ label: a.label, kg: a.txns })),
    },
    {
      id: 'kg-per-bill',
      option: 'kg on one bill',
      blurb: 'Average kilograms on one counted invoice.',
      title: 'Average kg per bill',
      ico: 'receipt',
      kind: 'bars',
      axis: 'Heavier bills carry more carbon per document.',
      max: perBillMax,
      bars: perBillRows,
    },
    {
      id: 'invoices',
      option: 'Each invoice this month',
      blurb: 'Kilograms on the counted bills.',
      title: 'Invoices this month',
      ico: 'receipt',
      kind: 'meters',
      axis: `These ${p.txns.length} invoices make up ${p.score.monthTotal} kg.`,
      meters: p.txns.map((t) => ({
        label: t.vendor,
        sub: t.type,
        value: `${t.emissions.toFixed(2)} kg`,
        pct: Math.round((t.emissions / invoiceMax) * 100),
        raw: t.emissions,
        icon: 'receipt' as W06IconName,
      })),
    },
    {
      id: 'intensity',
      option: 'kg per ₹1,000',
      blurb: 'Spend intensity. That is the factor printed on each bill.',
      title: 'kg per ₹1,000 spent',
      ico: 'meter',
      kind: 'meters',
      axis: `${p.score.monthTotal} kg this month · ${p.company.employees} people on site.`,
      meters: p.txns.map((t) => ({
        label: t.vendor,
        sub: t.type,
        value: `${t.factor.toFixed(2)} kg / ₹1,000`,
        pct: Math.round((t.factor / factorMax) * 100),
        raw: t.factor,
        icon: 'meter' as W06IconName,
      })),
      note: p.company.employees > 0
        ? `Per person this month: ${(p.score.monthTotal / p.company.employees).toFixed(2)} kg.`
        : undefined,
    },
    {
      id: 'plan',
      option: 'If you take the plan',
      blurb: "Waterfall of the reduction ideas against this month's total.",
      title: 'If you take the reduction plan',
      ico: 'mitigation',
      kind: 'waterfall',
      axis: `Cuts stack from this month's ${p.score.monthTotal} kg. Nothing here is a purchased offset.`,
      fall: buildReductionWaterfall(
        p.score.monthTotal,
        p.recs.map((r) => ({ label: r.title, impactKg: r.reduction }))
      ),
    },
  ];
}

/* ------------------------------------------------------------------ */
/*  Default instances (seed fallback for module-level consumers)       */
/* ------------------------------------------------------------------ */

const DEFAULT_PARAMS: AnalyticsDataParams = {
  assessments: ASSESSMENTS,
  chartMax: CHART_MAX,
  score: SCORE,
  txns: TXNS,
  recs: RECS,
  company: COMPANY,
};

export const MONTHS_CHART: AnalyticsChart = buildMonthsChart(DEFAULT_PARAMS);
export const ANALYTICS_CATALOG: AnalyticsCatalogItem[] = buildCatalog(DEFAULT_PARAMS);

export { buildMonthsChart, buildCatalog };

export function getCatalogItem(id: AnalyticsPinId): AnalyticsCatalogItem | undefined {
  return ANALYTICS_CATALOG.find((g) => g.id === id);
}

export function parsePinnedGraphs(search: string | null | undefined): AnalyticsPinId[] {
  const raw = new URLSearchParams(search || '').get('graphs') || '';
  const seen = new Set<AnalyticsPinId>();
  const out: AnalyticsPinId[] = [];
  raw.split(',').forEach((part) => {
    const id = part.trim();
    if (!isPinId(id) || seen.has(id)) return;
    seen.add(id);
    out.push(id);
  });
  return out;
}

export function togglePinnedGraph(current: AnalyticsPinId[], id: AnalyticsPinId): AnalyticsPinId[] {
  if (current.includes(id)) return current.filter((x) => x !== id);
  return [...current, id];
}

export function analyticsPinsHref(ids: AnalyticsPinId[]): string {
  const base = footprintHref('analytics');
  if (ids.length === 0) return base;
  return `${base}&graphs=${ids.join(',')}`;
}
