export type PageKey =
  | 'dashboard' | 'company' | 'upload' | 'footprint' | 'compliance' | 'targets' | 'offsets'
  | 'finance' | 'copilot' | 'settings' | 'help' | 'operations' | 'carbonTwin' | 'forecasting'
  | 'india' | 'exportTrack' | 'buyerAudit' | 'reporting' | 'targetsCharts' | 'savings'
  | 'offsetProjects' | 'offsetWallet' | 'offsetTrends' | 'offsetHistory' | 'adeetie'
  | 'greenLoans' | 'giftSchemes' | 'giftApps' | 'information' | 'billing' | 'dataPrivacy';

export type DataTab = 'bills' | 'connectors' | 'processed';
export type FpTab = 'overview' | 'bills' | 'analytics' | 'ideas';

export const PAGE_HREF: Record<PageKey, string> = {
  dashboard: '/dashboard',
  company: '/msme-profile',
  operations: '/operations',
  upload: '/document-upload',
  footprint: '/carbon-footprint?section=overview',
  carbonTwin: '/carbon-twin',
  forecasting: '/carbon-forecasting',
  compliance: '/compliance',
  india: '/compliance/india',
  exportTrack: '/compliance/export',
  buyerAudit: '/buyer-audit',
  reporting: '/reporting',
  targets: '/emissions-reduction-targets',
  targetsCharts: '/emissions-reduction-targets?section=charts',
  savings: '/carbon-savings',
  offsets: '/carbon-marketplace',
  offsetProjects: '/carbon-marketplace?tab=projects',
  offsetWallet: '/carbon-marketplace?tab=wallet',
  offsetTrends: '/carbon-marketplace?tab=trends',
  offsetHistory: '/carbon-marketplace?tab=history',
  finance: '/finance',
  adeetie: '/adeetie',
  greenLoans: '/green-loans',
  giftSchemes: '/gift-schemes',
  giftApps: '/gift-applications',
  copilot: '/ai-advisor',
  settings: '/settings',
  help: '/help',
  information: '/information',
  billing: '/billing',
  dataPrivacy: '/data-privacy',
};

export function uploadHref(tab: DataTab): string {
  if (tab === 'bills') return '/document-upload';
  return `/data?section=${tab}`;
}

export function footprintHref(tab: FpTab): string {
  const map: Record<FpTab, string> = {
    overview: '/carbon-footprint?section=overview',
    bills: '/carbon-footprint?section=operational',
    analytics: '/carbon-footprint?section=carbon-analytics',
    ideas: '/carbon-footprint?section=recommendations',
  };
  return map[tab];
}

export function resolvePage(pathname: string, search: string): { page: PageKey; dataTab: DataTab; fpTab: FpTab } {
  const q = new URLSearchParams(search);
  const section = q.get('section') || '';
  const tab = q.get('tab') || '';

  let dataTab: DataTab = 'bills';
  if (pathname === '/data' && section === 'connectors') dataTab = 'connectors';
  if (pathname === '/data' && section === 'processed') dataTab = 'processed';
  if (pathname === '/document-upload' || pathname === '/document-management' || pathname === '/documents') dataTab = 'bills';

  let fpTab: FpTab = 'overview';
  if (section === 'operational') fpTab = 'bills';
  if (section === 'carbon-analytics') fpTab = 'analytics';
  if (section === 'recommendations') fpTab = 'ideas';

  const table: Array<[string, PageKey]> = [
    ['/dashboard', 'dashboard'],
    ['/msme-profile', 'company'],
    ['/operations', 'operations'],
    ['/document-upload', 'upload'],
    ['/data', 'upload'],
    ['/document-management', 'upload'],
    ['/documents', 'upload'],
    ['/carbon-twin', 'carbonTwin'],
    ['/carbon-forecasting', 'forecasting'],
    ['/carbon-footprint', 'footprint'],
    ['/compliance/india', 'india'],
    ['/compliance/export', 'exportTrack'],
    ['/compliance', 'compliance'],
    ['/buyer-audit', 'buyerAudit'],
    ['/reporting', 'reporting'],
    ['/emissions-reduction-targets', 'targets'],
    ['/carbon-savings', 'savings'],
    ['/carbon-marketplace', 'offsets'],
    ['/carbon-trading', 'offsets'],
    ['/finance', 'finance'],
    ['/adeetie', 'adeetie'],
    ['/green-loans', 'greenLoans'],
    ['/gift-schemes', 'giftSchemes'],
    ['/gift-applications', 'giftApps'],
    ['/carbon-copilot', 'copilot'],
    ['/ai-advisor', 'copilot'],
    ['/settings', 'settings'],
    ['/help', 'help'],
    ['/information', 'information'],
    ['/billing', 'billing'],
    ['/data-privacy', 'dataPrivacy'],
  ];

  let page: PageKey = 'dashboard';
  for (const [path, key] of table) {
    if (pathname === path || (path !== '/compliance' && pathname.startsWith(`${path}/`))) {
      page = key;
      break;
    }
  }

  if (pathname === '/emissions-reduction-targets' && section === 'charts') page = 'targetsCharts';
  if (pathname === '/carbon-marketplace' || pathname === '/carbon-trading') {
    if (tab === 'projects') page = 'offsetProjects';
    else if (tab === 'wallet') page = 'offsetWallet';
    else if (tab === 'trends') page = 'offsetTrends';
    else if (tab === 'history') page = 'offsetHistory';
  }

  return { page, dataTab, fpTab };
}

export type NavChild = {
  page: PageKey;
  label: string;
  ico: string;
  tab?: DataTab;
  fp?: FpTab;
};

export type NavTopic = { page: PageKey; children: NavChild[] };

export function navTopics(expert: boolean, hasAssessment: boolean, hasExportIntent: boolean): {
  primary: NavTopic[];
  secondary: NavTopic[];
} {
  const primary: NavTopic[] = [
    { page: 'dashboard', children: [] },
    {
      page: 'company',
      children: [
        { page: 'company', label: 'Company profile', ico: 'factoryId' },
        { page: 'operations', label: 'Operations', ico: 'opsCard' },
      ],
    },
    {
      page: 'upload',
      children: [
        { page: 'upload', label: 'Upload bills', ico: 'dropTitle', tab: 'bills' },
        { page: 'upload', label: 'Data connectors', ico: 'connect', tab: 'connectors' },
      ],
    },
    {
      page: 'footprint',
      children: [
        { page: 'footprint', label: 'Overview', ico: 'score', fp: 'overview' },
        { page: 'footprint', label: 'Bills & activity', ico: 'txnTitle', fp: 'bills' },
        ...(expert ? [{ page: 'footprint' as PageKey, label: 'Analytics', ico: 'analytics', fp: 'analytics' as FpTab }] : []),
        { page: 'carbonTwin', label: 'CarbonTwin', ico: 'twin' },
        { page: 'footprint', label: 'Reduction ideas', ico: 'mitigation', fp: 'ideas' },
        ...(hasAssessment ? [{ page: 'forecasting' as PageKey, label: 'Forecasting', ico: 'trend' }] : []),
      ],
    },
    {
      page: 'compliance',
      children: [
        { page: 'compliance', label: 'Overview', ico: 'readiness' },
        { page: 'india', label: 'India market', ico: 'india' },
        ...(hasExportIntent
          ? [
              { page: 'exportTrack' as PageKey, label: 'Global export', ico: 'globe' },
              { page: 'buyerAudit' as PageKey, label: 'Buyer audit pack', ico: 'pack' },
            ]
          : []),
        { page: 'reporting', label: 'Disclosure reports', ico: 'reports' },
      ],
    },
    {
      page: 'targets',
      children: [
        { page: 'targetsCharts', label: 'Progress & charts', ico: 'analytics' },
        { page: 'targets', label: 'Targets', ico: 'targets' },
        { page: 'savings', label: 'Carbon savings', ico: 'mitigation' },
      ],
    },
  ];
  if (expert) {
    if (hasAssessment) {
      primary.push({
        page: 'offsets',
        children: [
          { page: 'offsetProjects', label: 'Offset projects', ico: 'turbine' },
          { page: 'offsetWallet', label: 'Credits wallet', ico: 'wallet' },
          { page: 'offsetTrends', label: 'Market trends', ico: 'trend' },
          { page: 'offsetHistory', label: 'Trade history', ico: 'period' },
        ],
      });
    }
    primary.push({
      page: 'finance',
      children: [
        { page: 'finance', label: 'Overview', ico: 'finance' },
        ...(hasAssessment ? [{ page: 'adeetie' as PageKey, label: 'Energy efficiency (ADEETIE)', ico: 'hub' }] : []),
        { page: 'greenLoans', label: 'Green loans', ico: 'loans' },
        { page: 'giftSchemes', label: 'GIFT schemes', ico: 'schemes' },
        ...(hasAssessment ? [{ page: 'giftApps' as PageKey, label: 'My applications', ico: 'invoice' }] : []),
      ],
    });
    primary.push({ page: 'copilot', children: [] });
  }
  const secondary: NavTopic[] = expert
    ? [
        { page: 'information', children: [] },
        { page: 'billing', children: [] },
        { page: 'dataPrivacy', children: [] },
        { page: 'settings', children: [] },
        { page: 'help', children: [] },
      ]
    : [
        { page: 'settings', children: [] },
        { page: 'help', children: [] },
      ];
  return { primary, secondary };
}

export function childHref(c: NavChild): string {
  if (c.tab) return uploadHref(c.tab);
  if (c.fp) return footprintHref(c.fp);
  return PAGE_HREF[c.page];
}

export function childActive(c: NavChild, page: PageKey, dataTab: DataTab, fpTab: FpTab): boolean {
  if (c.tab) return page === 'upload' && dataTab === c.tab;
  if (c.fp) return page === 'footprint' && fpTab === c.fp;
  return c.page === page;
}

export function topicDefaultActive(t: NavTopic, page: PageKey, dataTab: DataTab, fpTab: FpTab): boolean {
  if (!t.children.length) return t.page === page;
  if (t.children.some((c) => childActive(c, page, dataTab, fpTab))) return false;
  return t.page === page;
}

export function findTopic(page: PageKey, expert: boolean, hasA: boolean, exp: boolean): NavTopic | null {
  const { primary, secondary } = navTopics(expert, hasA, exp);
  for (const t of [...primary, ...secondary]) {
    if (t.page === page) return t;
    if (t.children.some((c) => c.page === page)) return t;
  }
  return null;
}

