import React from 'react';
import { publicAssetUrl } from '../constants/brand';
import { Ico, type W06IconName } from './Ico';
import { PAGES, type ScopeRow } from './seed';

export function inr(n: number): string {
  return `₹${n.toLocaleString('en-IN')}`;
}

export const Skeleton: React.FC<{ w?: string; h?: number; lines?: number }> = ({
  w = '100%',
  h = 16,
  lines = 1,
}) => (
  <div className="skeleton-group" aria-hidden="true">
    {Array.from({ length: lines }, (_, i) => (
      <div
        key={i}
        className="skeleton"
        style={{ width: i === lines - 1 && lines > 1 ? '60%' : w, height: h }}
      />
    ))}
  </div>
);

export function statusClass(s: string): string {
  const m: Record<string, string> = {
    Processed: 'green', Ready: 'green', Good: 'green', 'On track': 'green', Connected: 'green',
    Pending: 'amber', 'In review': 'amber', Gap: 'red', high: 'red', medium: 'amber', low: 'green',
  };
  return m[s] || '';
}

export const Chip: React.FC<{ children: string }> = ({ children }) => (
  <span className={`chip ${statusClass(children)}`}><span className="dot" />{children}</span>
);

export const PageHead: React.FC<{ page: string; desc?: string }> = ({ page, desc }) => {
  const p = PAGES[page];
  if (!p) return null;
  return (
    <div className="page-head">
      <Ico name={p.ico} />
      <div>
        <h1>{p.label}</h1>
        <p>{desc || p.desc}</p>
      </div>
    </div>
  );
};

export const Card: React.FC<{
  title: string;
  icon: W06IconName | string;
  tail?: string;
  action?: React.ReactNode;
  nba?: boolean;
  children: React.ReactNode;
}> = ({ title, icon, tail, action, nba, children }) => (
  <section className={nba ? 'card nba' : 'card'}>
    <h2>
      <Ico name={icon} />
      {title}
      {tail ? <span className="tail">{tail}</span> : null}
      {action}
    </h2>
    {children}
  </section>
);

export const ScopeCard: React.FC<{ scope: ScopeRow }> = ({ scope }) => (
  <article className="card scope-card">
    <figure className="scope-card-fig">
      <img src={publicAssetUrl(scope.img)} alt={scope.alt} />
    </figure>
    <h2>
      <Ico name={scope.ico} color={scope.color} />
      {scope.tag}
    </h2>
    <p className="scope-card-sub">{scope.sub}</p>
    <p className="scope-card-explain">{scope.explain}</p>
    <div className="scope-card-meter">
      <div
        className="track"
        role="meter"
        aria-label={`${scope.tag} share of this month`}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={scope.pct}
      >
        <i style={{ width: `${scope.pct}%`, background: scope.color }} />
      </div>
      <span className="pct">{scope.pct}%</span>
      <span className="v">{scope.val.toFixed(2)} kg</span>
    </div>
  </article>
);

export const MeterRow: React.FC<{
  label: string;
  sub?: string;
  value: React.ReactNode;
  pct: number;
  color: string;
  icon?: W06IconName | string;
  pctText?: string | false;
  first?: boolean;
}> = ({ label, sub, value, pct, color, icon, pctText }) => {
  const p = pctText === false ? '' : pctText === undefined ? `${pct}%` : pctText;
  return (
    <div className="row">
      {icon ? <Ico name={icon} color={color} /> : <span className="swatch" style={{ background: color }} />}
      <div>
        <span className="k">{label}</span>
        {sub ? <span className="sub">{sub}</span> : null}
      </div>
      <div className="track" aria-hidden="true"><i style={{ width: `${pct}%`, background: color }} /></div>
      {p ? <span className="pct">{p}</span> : null}
      <span className="v">{value}</span>
    </div>
  );
};

export const TextRow: React.FC<{ label: string; value: React.ReactNode; pct: string; color: string }> = ({
  label, value, pct, color,
}) => (
  <div className="row">
    <span className="swatch" style={{ background: color }} />
    <div><span className="k">{label}</span></div>
    <span className="pct">{pct}</span>
    <span className="v">{value}</span>
  </div>
);

export const ActionRow: React.FC<{
  icon?: W06IconName | string;
  color?: string;
  k: string;
  sub?: string;
  status?: string;
  v?: string;
  trailing?: React.ReactNode;
}> = ({ icon, color, k, sub, status, v, trailing }) => (
  <div className="row">
    {icon ? (color ? <Ico name={icon} color={color} /> : <Ico name={icon} />) : <Ico name="fwMark" />}
    <div>
      <span className="k">{k}</span>
      {sub ? <span className="sub">{sub}</span> : null}
    </div>
    {status ? <Chip>{status}</Chip> : null}
    {v ? <span className="v">{v}</span> : null}
    {trailing}
  </div>
);

export const Empty: React.FC<{
  icon: W06IconName | string;
  title: string;
  text: string;
  cta?: string;
  onCta?: () => void;
}> = ({ icon, title, text, cta, onCta }) => (
  <div className="empty">
    <Ico name={icon} />
    <h3>{title}</h3>
    <p>{text}</p>
    {cta ? <button type="button" className="btn" onClick={onCta}>{cta}</button> : null}
  </div>
);

export const Dl: React.FC<{ rows: Array<[string, string]> }> = ({ rows }) => (
  <dl className="dl">
    {rows.map(([dt, dd]) => (
      <React.Fragment key={dt}>
        <dt>{dt}</dt>
        <dd>{dd}</dd>
      </React.Fragment>
    ))}
  </dl>
);

export const Stamps: React.FC<{ rows: Array<{ name?: string; k?: string; status?: string; sub?: string; ico: W06IconName | string }> }> = ({ rows }) => (
  <div className={rows.length <= 3 ? 'stamps few' : 'stamps'}>
    {rows.map((r) => {
      const name = r.name || r.k || '';
      const sub = r.status || r.sub || '';
      return (
        <div className="stamp" key={name}>
          <Ico name={r.ico} />
          <b>{name}</b>
          <span>{sub}</span>
        </div>
      );
    })}
  </div>
);

export const Sheets: React.FC<{ title: string; icon: W06IconName | string }> = ({ title, icon }) => (
  <div className="sheets" role="img" aria-label={title}>
    <span className="sheet" />
    <span className="sheet" />
    <div className="sheet">
      <Ico name={icon} />
      <b>{title}</b>
    </div>
  </div>
);

export const Colonnade: React.FC = () => (
  <div className="colonnade" role="img" aria-label="Term finance">
    <div className="roof" />
    <div className="piers"><b /><b /><b /><b /></div>
  </div>
);

export const BarChart: React.FC<{
  bars: Array<{ label: string; kg: number; forecast?: boolean; color?: string }>;
  max: number;
  axis: string;
}> = ({ bars, max, axis }) => (
  <>
    <div className="chart">
      {bars.map((a) => (
        <div className={a.forecast ? 'bar fcst' : 'bar'} key={a.label}>
          <b>{a.kg}</b>
          <i
            style={{
              height: `${Math.round((a.kg / max) * 72)}%`,
              ...(a.color ? { background: a.color } : {}),
            }}
          />
          <span>{a.label}</span>
        </div>
      ))}
    </div>
    <p className="axis">{axis}</p>
  </>
);

export const Note: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <p className="note">{children}</p>
);

export const Figure: React.FC<{ src: string; cap: string }> = ({ src, cap }) => (
  <figure className="figure">
    <img src={src} alt="" />
    <figcaption>{cap}</figcaption>
  </figure>
);

export const RecRow: React.FC<{
  title: string;
  cost: number;
  payback: string;
  reduction: number;
  ico: W06IconName | string;
  selectable?: boolean;
  selected?: boolean;
  onSelect?: () => void;
}> = ({ title, cost, payback, reduction, ico, selectable, selected, onSelect }) => (
  <div className="row">
    <Ico name={ico} />
    <div>
      <span className="k">{title}</span>
      <span className="sub">{inr(cost)} · pays back in {payback}</span>
    </div>
    <span className="v">−{reduction} kg</span>
    {selectable ? (
      <button type="button" className={`btn sm${selected ? '' : ' ghost'}`} onClick={onSelect}>
        {selected ? <><Ico name="selected" />Selected</> : 'Select'}
      </button>
    ) : null}
  </div>
);

export const CheckRow: React.FC<{
  done: boolean;
  k: string;
  sub: string;
  action?: React.ReactNode;
}> = ({ done, k, sub, action }) => (
  <div className={`check${done ? ' done' : ''}`}>
    <span className="mark" aria-hidden="true"><Ico name="gapTick" wrap={false} /></span>
    <div>
      <span className="k">{k}</span>
      <span className="sub">{sub}</span>
    </div>
    {action}
  </div>
);

export const Modal: React.FC<{
  open: boolean;
  title: string;
  titleId: string;
  icon: W06IconName | string;
  onClose: () => void;
  foot: React.ReactNode;
  children: React.ReactNode;
}> = ({ open, title, titleId, icon, onClose, foot, children }) => {
  React.useEffect(() => {
    if (!open) return undefined;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [open]);
  if (!open) return null;
  return (
    <div className="modal open" role="dialog" aria-modal="true" aria-labelledby={titleId} aria-hidden="false">
      <div className="backdrop" data-close-modal="" onClick={onClose} />
      <div className="panel" role="document">
        <div className="m-head">
          <Ico name={icon} />
          <h3 id={titleId}>{title}</h3>
          <button className="x" type="button" data-close-modal="" aria-label="Close" onClick={onClose}>
            <Ico name="close" wrap={false} />
          </button>
        </div>
        {children}
        <div className="m-foot">{foot}</div>
      </div>
    </div>
  );
};

